const APP_TEXT_WRAP_GUARD = {
  maxWidth: "100%" as const,
  flexShrink: 1 as const,
};

// Apple HIG accessibility: honour the system "Reduce Motion" setting. Returns
// true when the user has asked the OS to minimise animation, so the decorative
// looping pulses (loading shimmers, the typing-dots beat, CTA breathing) can
// hold still instead of animating. Defaults to false, so if detection is
// unavailable the app behaves exactly as before -- purely additive.
// Settles a fast-changing value -- draft text, in practice -- so work keyed
// off it runs when the person pauses rather than on every character.
//
// buildRoutePreview() runs roughly 32 regular expressions across the whole
// text (route detection, issue detection, redress-route detection). It feeds
// three live previews: the Home issue box, the journal, and the counselling
// composer. All three were recomputing that on every keystroke, so writing a
// paragraph-long journal entry ran the full battery hundreds of times to
// produce a hint that only needs to be right when someone stops to read it.
//
// 220ms is under the ~250ms that reads as "instant" after a pause, so the
// preview still feels immediate -- it just no longer competes with typing.
function useDebouncedValue<T>(value: T, delayMs = 220): T {
  const [settled, setSettled] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setSettled(value), delayMs);
    return () => clearTimeout(timer);
  }, [value, delayMs]);
  return settled;
}

function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    let mounted = true;
    AccessibilityInfo.isReduceMotionEnabled?.().then((v) => { if (mounted) setReduced(!!v); }).catch(() => {});
    const sub = AccessibilityInfo.addEventListener?.("reduceMotionChanged", (v: boolean) => setReduced(!!v));
    return () => { mounted = false; sub?.remove?.(); };
  }, []);
  return reduced;
}

// ── Disclosure motion ───────────────────────────────────────────────────────
// Every expand/collapse in the app snapped instantly: panels appeared and
// vanished between frames, which is the single clearest tell between this and
// a first-party Apple or Samsung app, where disclosure is always a movement
// you can follow. LayoutAnimation gives that for free on the next layout pass,
// but on Android's old architecture it has to be switched on explicitly.
if (Platform.OS === "android" && UIManager.setLayoutAnimationEnabledExperimental) {
  UIManager.setLayoutAnimationEnabledExperimental(true);
}

// Read once per call rather than through the useReducedMotion hook, because
// this is invoked from plain event handlers, not from render. Cached because
// the OS setting changes rarely and an await here would land the animation a
// frame late -- after the state update it is supposed to describe.
let _aethonReduceMotion = false;
AccessibilityInfo.isReduceMotionEnabled?.()
  .then((v) => { _aethonReduceMotion = !!v; })
  .catch(() => {});
AccessibilityInfo.addEventListener?.("reduceMotionChanged", (v: boolean) => {
  _aethonReduceMotion = !!v;
});

// Call immediately BEFORE the setState that changes layout.
// 220ms on an ease-out curve: long enough to read as movement, short enough
// that a person opening four panels in a row never waits on it. Opacity is
// animated on entry/exit so content fades in rather than popping, while
// height/position eases -- the same shape as a UIKit disclosure.
function animateDisclosure(): void {
  if (_aethonReduceMotion) return;
  LayoutAnimation.configureNext({
    duration: 220,
    create: { type: LayoutAnimation.Types.easeOut, property: LayoutAnimation.Properties.opacity },
    update: { type: LayoutAnimation.Types.easeInEaseOut },
    delete: { type: LayoutAnimation.Types.easeIn, property: LayoutAnimation.Properties.opacity }
  });
}

// ── Chat composer ───────────────────────────────────────────────────────────
// App() is a single ~6,600-line component holding 183 pieces of state. Any
// setState in it re-renders the whole active tab: every inline style object
// rebuilt, all 85 useMemo dependency arrays compared. When the draft text of
// a chat box lives up there, that entire pass runs on every keystroke, which
// is what makes typing feel heavy on a mid-range Android.
//
// Keeping the draft inside a memoised composer confines the per-keystroke
// render to this component. The parent is only told when the message is
// actually sent. onSubmit is the one prop that must stay referentially
// stable for the memo to hold -- it is a plain function declaration in App(),
// so it does.
const ChatComposer = React.memo(function ChatComposer({
  placeholder,
  submitLabel,
  busyLabel,
  editable,
  busy,
  onSubmit,
  accessibilityLabel
}: {
  placeholder: string;
  submitLabel: string;
  busyLabel: string;
  editable: boolean;
  busy: boolean;
  onSubmit: (text: string) => void;
  accessibilityLabel?: string;
}) {
  const [draft, setDraft] = useState("");
  const canSend = editable && !busy && draft.trim().length > 0;
  return (
    <View style={{
      backgroundColor: "#E1EEEC", borderRadius: 12, padding: 10, gap: 8,
      borderWidth: 1, borderColor: "rgba(252,211,77,0.2)"
    }}>
      <TextInput
        value={draft}
        onChangeText={setDraft}
        placeholder={placeholder}
        placeholderTextColor="rgba(13,31,34,0.4)"
        accessibilityLabel={accessibilityLabel}
        multiline
        editable={editable}
        style={{ color: "#0D1F22", fontSize: 14, minHeight: 46, lineHeight: 20, padding: 8 }}
      />
      <View style={{ flexDirection: "row", justifyContent: "flex-end", gap: 8 }}>
        <Pressable
          onPress={() => {
            const text = draft.trim();
            if (text.length === 0) return;
            // Cleared here rather than by the parent, so the box empties on
            // the same frame as the send.
            setDraft("");
            onSubmit(text);
          }}
          disabled={!canSend}
          accessibilityRole="button"
          accessibilityState={{ disabled: !canSend }}
          style={({ pressed }) => ({
            backgroundColor: !canSend ? "#334155" : (pressed ? "#A14A08" : "#D97706"),
            borderRadius: 10, paddingHorizontal: 16, paddingVertical: 9
          })}
        >
          <Text style={{ color: "#FFFFFF", fontSize: 13, fontWeight: "800" }}>
            {busy ? busyLabel : submitLabel}
          </Text>
        </Pressable>
      </View>
    </View>
  );
});

function Text({ style, ...props }: TextProps) {
  return <RNText {...props} style={[APP_TEXT_WRAP_GUARD, style]} />;
}

const TextWithDefaults = RNText as unknown as { defaultProps?: Record<string, unknown> };
const TextInputWithDefaults = TextInput as unknown as { defaultProps?: Record<string, unknown> };

// Dynamic Type ceiling. This was 1.35, which is well under what the layout
// can actually take. Measured on the deployed build by scaling every rendered
// text node and looking for real failures rather than assuming:
//
//   1.35x   nothing clipped, nothing escaped its parent
//   2.0x    nothing clipped, nothing escaped -- 8 nav labels ellipsised,
//           which is numberOfLines={1} degrading correctly, not breaking
//   3.0x    first real damage: a badge letter cut off, "Pending verification"
//           escaping its container
//
// So the cap was denying people text the layout would have handled fine.
// Someone who turns on Larger Accessibility Sizes because they need it was
// getting a third of what they asked for, for no structural reason.
//
// Raised to 1.8 rather than the 2.0 the evidence supports: those numbers come
// from a 792px-wide render, and the phone layout has far less horizontal room,
// so labels will ellipsise earlier there. 1.8 takes most of the available
// headroom while leaving margin for the narrower case I could not measure.
// If the phone build holds at 1.8, this can go to 2.0.
const MAX_FONT_SCALE = 1.8;

TextWithDefaults.defaultProps = {
  ...(TextWithDefaults.defaultProps ?? {}),
  allowFontScaling: true,
  maxFontSizeMultiplier: MAX_FONT_SCALE
};

TextInputWithDefaults.defaultProps = {
  ...(TextInputWithDefaults.defaultProps ?? {}),
  allowFontScaling: true,
  maxFontSizeMultiplier: MAX_FONT_SCALE
};

