// Canonical urgent-safety keyword detector — the single source of truth for
// "does this text describe an immediate safety risk" (self-harm, suicide,
// assault, abuse, violence, emergency). Previously this lived as two
// separately-maintained regexes (one in detectGuidedSupportRouteFromText, one in
// buildPrivateIntakeReport's hasSafetyCue) that had quietly drifted apart --
// e.g. one had "dangerous" and "crisis"/"panic", the other didn't; one had
// "rape"/"assaulted" phrasing, the other didn't. A future edit to one would
// not have propagated to the other, silently reintroducing a gap.
//
// This consolidated pattern is the UNION of every keyword either of the two
// original regexes matched, so merging them cannot reduce detection
// sensitivity anywhere it's used -- only keep it the same or catch more.
// Callers should lowercase their input before testing (matching prior
// behavior at both call sites); the /i flag is added defensively in case a
// future caller forgets.
const URGENT_SAFETY_SIGNAL_PATTERN =
  /(emergency|unsafe|danger|dangerous|suicid|self[-\s]?harm|kill myself|hurt myself|end my life|end it all|don't want to live|don't want to be here|assault|assaulted|rape|sexual assault|being abused|abuse|abused|physical violence|violence|threat|threat to my life|being threatened|threatened|crisis|panic|112|911|999)/i;

function isUrgentSafetySignal(text: string): boolean {
  return classifyCounsellingSafety(text) === "immediate" || URGENT_SAFETY_SIGNAL_PATTERN.test(text);
}

// ── Verified crisis lifelines (India) ───────────────────────────────────────
// Government-operated, free, 24x7, multi-language. Verified against official
// PIB / Ministry sources on 2026-07-31. When a self-directed safety signal
// (self-harm / suicidal ideation) is detected, the app leads with these
// IMMEDIATELY — never a conversational reply or a complaint flow. Re-verify
// these numbers before each release; helplines change.
const CRISIS_HELPLINES: { name: string; dial: string; detail: string }[] = [
  { name: "Tele-MANAS", dial: "14416", detail: "National mental-health helpline (Govt. of India, MoHFW). Free, 24x7, 20 languages." },
  { name: "Tele-MANAS (alt)", dial: "1800-891-4416", detail: "Toll-free alternate line for Tele-MANAS if 14416 does not connect." },
  { name: "KIRAN", dial: "1800-599-0019", detail: "Mental-health rehabilitation helpline (Govt. of India). Free, 24x7, 13 languages." },
  { name: "Emergency (112)", dial: "112", detail: "Pan-India emergency — police, ambulance, fire. Use if there is immediate danger to life." }
];

// Escapes user/content text for safe embedding in the print HTML below.
function escapeHtmlForPrint(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

// Builds a clean, printable A4 HTML document for a complaint letter, then opens
// the OS print / "Save as PDF" dialog via expo-print (works on iOS, Android and
// web). Whitespace is preserved so the letter's line breaks survive.
async function exportComplaintLetterPdf(letterText: string, routeLabel: string): Promise<void> {
  const html = `<!DOCTYPE html><html><head><meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <style>
      @page { margin: 24mm 18mm; }
      body { font-family: Georgia, "Times New Roman", serif; color: #10151b; font-size: 13pt; line-height: 1.6; }
      .meta { font-size: 9pt; color: #6a7683; border-top: 1px solid #d6dee5; margin-top: 28px; padding-top: 8px; }
      pre { white-space: pre-wrap; word-wrap: break-word; font-family: Georgia, "Times New Roman", serif; margin: 0; }
    </style></head>
    <body>
      <pre>${escapeHtmlForPrint(letterText)}</pre>
      <div class="meta">Prepared with NAYIQ · ${escapeHtmlForPrint(routeLabel)} · Verify all bracketed details and keep a signed copy.</div>
    </body></html>`;
  await Print.printAsync({ html });
}

// ── Positive / neutral check-in detector ────────────────────────────────────
// Bug this exists to fix: the "emotional context" classifier below matches on
// the bare words "feel" / "feeling" / "felt" so it can catch phrasing like
// "I feel so alone" — but that same bare match also fires on "I am feeling
// energetic", "I feel great today", etc. Every downstream step (the
// counselling acknowledgment, the question bank, the synthesis) assumes
// distress, so a genuinely positive message was being answered with "Whatever
// you are carrying right now is real..." — a reply that has nothing to do
// with what was actually typed. This detector runs BEFORE the emotional-
// context check so a clearly positive, no-distress-signal message short-
// circuits into a correctly-toned reply instead of the counselling engine.
const POSITIVE_CHECKIN_PATTERN =
  /(feeling energetic|feel energetic|feeling good|feel good|feeling great|feel great|feeling fine|feel fine|feeling well|feel well|feeling happy|feel happy|feeling positive|feel positive|feeling amazing|feel amazing|feeling wonderful|feel wonderful|feeling fantastic|feel fantastic|feeling motivated|feel motivated|feeling confident|feel confident|feeling proud|feel proud|feeling hopeful|feel hopeful|feeling optimistic|feel optimistic|feeling grateful|feel grateful|feeling thankful|feel thankful|feeling blessed|feel blessed|feeling calm|feel calm|feeling peaceful|feel peaceful|feeling relaxed|feel relaxed|feeling content|feel content|feeling satisfied|feel satisfied|feeling productive|feel productive|feeling accomplished|feel accomplished|feeling refreshed|feel refreshed|feeling alive|feel alive|feeling strong|feel strong|feeling better|feel better|feeling excited|feel excited|feeling joyful|feel joyful|feeling cheerful|feel cheerful|doing well|doing great|doing good|doing fine|doing fantastic|in a good place|on top of the world|really happy|so happy|very happy|great mood|good mood|feeling my best|life is good|things are going well|things are good|had a great day|had a good day|great day today|good day today)/;

// Negative/distress vocabulary reused from the checks further down (minus the
// bare "feel/feeling/felt" words that cause the false positive above). If any
// of this fires alongside a positive phrase — e.g. "I felt great until this
// happened, now I'm devastated" — the message is NOT treated as a pure
// positive check-in, and the normal distress routing still applies.
const NEGATIVE_SIGNAL_PATTERN =
  /(upset|sad|hurt|broken|low mood|feeling low|feeling down|lost|numb|empty|hollow|ignored|invisible|unappreciated|not appreciated|not valued|not noticed|not recognised|not recognized|not seen|ugly|unattractive|not good looking|body image|insecur|ashamed|embarrassed|unloved|unwanted|rejected|alone|lonely|worthless|hopeless|depress|exhausted|tired of|sick of|struggling|overwhelmed|angry|anger|rage|furious|irritat|frustrat|anxious|anxiety|stress|stressed|worry|worried|panic|nervous|grief|griev|mourning|mourn|bereaved|bereavement|lost someone|someone died|passed away|divorce|separation|breakup|broke up|cheating|affair|marriage problem|relationship problem|job loss|lost my job|fired|laid off|redundant|money problem|debt|broke|financial trouble|loan|can.t pay|meaningless|addicted|can.t stop|complaint|grievance|redress|report|escalat|harass|bully|abuse|assault|trauma|suicid|self[-\s]?harm)/;

function isPositiveCheckIn(text: string): boolean {
  const n = text.toLowerCase();
  if (isUrgentSafetySignal(n)) return false;
  if (NEGATIVE_SIGNAL_PATTERN.test(n)) return false;
  return POSITIVE_CHECKIN_PATTERN.test(n);
}

// A positive check-in used to get one identical reply no matter which
// positive emotion was actually named -- "grateful" and "energetic" and
// "proud" all produced the same sentence. Real emotional understanding
// means the reply changes with the specific mood, the same way the 48
// support dimensions each get their own guidance instead of one shared
// template. Order matters: more specific emotion words are checked first.
function buildPositiveCheckInReply(text: string): { heard: string; nextStep: string } {
  const n = text.toLowerCase();
  if (/(grateful|thankful|blessed)/.test(n)) {
    return {
      heard: "That's a good thing to notice and name — gratitude tends to grow when it's put into words instead of only felt.",
      nextStep: "Write down what specifically you're grateful for in Journal, so it's easy to find again on a harder day."
    };
  }
  if (/(energetic|motivated|productive|accomplished|refreshed|feeling strong|feel strong|feeling alive|feel alive)/.test(n)) {
    return {
      heard: "Good energy is worth using, not just noticing — this is a genuinely useful window, not a permanent state.",
      nextStep: "Put some of that energy into one real thing you've been putting off, while it's here."
    };
  }
  if (/(proud|confident)/.test(n)) {
    return {
      heard: "That's worth sitting with for a moment instead of rushing past it — pride in real effort is earned, not indulgent.",
      nextStep: "Name specifically what you're proud of. It makes the feeling easier to draw on again later, on a harder day."
    };
  }
  if (/(calm|peaceful|relaxed|content|satisfied)/.test(n)) {
    return {
      heard: "That steadiness is real progress, not just the absence of a problem — it's worth recognising on its own terms.",
      nextStep: "No action needed here. If you'd like, use this calm state for something reflective in Path or Journal."
    };
  }
  if (/(hopeful|optimistic)/.test(n)) {
    return {
      heard: "Hope is genuinely useful, especially paired with one concrete next step rather than left as only a feeling.",
      nextStep: "If there's something specific you're hopeful about, one small action now tends to make the hope hold longer."
    };
  }
  if (/(excited|joyful|cheerful|fantastic|amazing|wonderful)/.test(n)) {
    return {
      heard: "Good to hear — let this be enjoyed for what it is, not only as a lead-up to whatever comes next.",
      nextStep: "If you want to remember this moment, a quick Journal note captures it better than memory usually does."
    };
  }
  return {
    heard: "That's genuinely good to hear — thank you for sharing something positive. Not every check-in here has to be about a problem.",
    nextStep: "Let me know if there is anything specific on your mind — otherwise, enjoy the moment."
  };
}

function detectGuidedSupportRouteFromText(text: string): GuidedSupportRoute {
  const n = text.toLowerCase();

  // ── 1. URGENT — immediate safety risk ──────────────────────────────────────
  if (isUrgentSafetySignal(n)) {
    return "urgent";
  }

  // ── 2. PROFESSIONAL — clinical-level symptoms that need expert care ─────────
  if (/(seeing things|hearing voices|hallucina|psychosis|psychotic|paranoi|ptsd|flashback|trauma|dissociat|bipolar|schizophrenia|eating disorder|anorexia|bulimia|binge eating|self medicate|overdose|withdrawal|detox|rehab|addict|addiction|alcoholic|drug depend|substance abuse|chronic pain|chronic illness|terminal|diagnosed with|diagnosis|cancer|heart condition|severe depression|clinical depression|cannot get out of bed for weeks|not eaten|haven't slept in days|suicidal thoughts|want to die)/.test(n)) {
    return "professional";
  }

  // ── 2.5 POSITIVE CHECK-IN — clearly positive affect, no distress signal ─────
  // Must run before the emotional-context check below, which matches on the
  // bare words "feel"/"feeling"/"felt" regardless of what follows them. That
  // bare match is what previously sent something like "I am feeling
  // energetic" into the distress-support flow.
  if (isPositiveCheckIn(n)) {
    return "general";
  }

  // ── 3. EMOTIONAL CONTEXT — must check BEFORE redress ────────────────────────
  // Any emotional, self-worth, relational, or life-situation keyword → guide
  const isEmotional = /(feel|feeling|felt|upset|sad|hurt|broken|low|down|lost|numb|empty|hollow|ignored|invisible|unappreciated|not appreciated|not valued|not noticed|not recognised|not recognized|not seen|looks|appearance|ugly|unattractive|not good looking|how i look|my body|body image|weight|fat|thin|self.worth|self.esteem|self.image|self.confidence|insecur|ashamed|embarrassed|unloved|unwanted|rejected|alone|lonely|worthless|hopeless|depressed|exhausted|tired of|sick of|struggling|overwhelmed|angry|anger|rage|furious|irritat|frustrat|anxious|anxiety|stress|stressed|worry|worried|panic|nervous|grief|griev|mourning|mourn|bereaved|bereavement|lost someone|someone died|passed away|divorce|separation|breakup|broke up|cheating|affair|marriage problem|relationship problem|my wife|my husband|my partner|my boyfriend|my girlfriend|my family|my parents|my kids|my children|job loss|lost my job|fired|laid off|redundant|money problem|debt|broke|financial|loan|rent|can.t pay|purpose|meaning|meaningless|lost my identity|addicted|can.t stop|habit|compulsion|school|exam|grades|marks|academic|study|parenting|my child|my son|my daughter|new baby|postpartum)/.test(n);
  if (isEmotional) return "guide";

  // ── 4. REDRESS — explicit formal complaint with action intent ────────────────
  const isRedress =
    /(complaint|grievance|redress|report|escalat|ragging|harass|bully|bullied|bullying|hod|principal|dean|authority|department|desk|police|cyber|file a|lodge a|take action|legal action|anti.ragging|icc|posh|hr complaint)/.test(n)
    || (/(professor|teacher|manager|hr|office|faculty)/.test(n) && /(complaint|report|escalat|harass|bully|action|file|lodge)/.test(n))
    || (/(senior|junior)/.test(n) && /(ragging|bully|harass|threat|complaint|report|abuse|intimidat)/.test(n))
    || (/(school|college|university|hostel|warden|campus)/.test(n) && /(complaint|grievance|report|escalat|ragging|harass|bully|bullied|teacher|principal|dean|authority)/.test(n));
  if (isRedress) return "redress";

  // ── 5. CALM EMOTIONAL — named emotions without clinical severity ─────────────
  if (/(anger|angry|irritat|anxiety|anxious|fear|afraid|overconfiden|stigma|shame|burnout|burned out|loneliness|stress|stressed|worry|worried|coward|confus|frustrat|overwhelmed|panic|sad|depress|low|hurt)/.test(n)) {
    return "guide";
  }

  return "general";
}

function findGuidedSupportIssueIdFromText(text: string): IssueId | null {
  const n = text.toLowerCase();

  // Order: most specific / clinical first, then emotional, then broad
  if (/(grief|griev|mourning|bereaved|bereavement|lost someone|someone died|passed away|death of|loss of|they died|she died|he died)/.test(n)) return "grief";
  if (/(trauma|ptsd|flashback|abuse|abused|assault|assaulted|molested|raped|violence against|domestic violence|childhood abuse)/.test(n)) return "trauma";
  if (/(addict|addiction|alcoholic|alcohol problem|drug|substance|gambling|can't stop drinking|can't stop using|compulsive|rehab|detox)/.test(n)) return "addiction";
  if (/(my child|my son|my daughter|my kids|my baby|parenting|new parent|postpartum|toddler|teenager|teen behaviour|child behaviour)/.test(n)) return "parenting";
  if (/(financial|money problem|debt|broke|bankrupt|loan|can't pay|rent|afford|salary cut|lost my job|job loss|fired|redundant|unemployed)/.test(n)) return "financial";
  if (/(illness|sick|chronic|diagnosis|diagnosed|cancer|heart|disease|disability|chronic pain|medical condition|health anxiety|doctor said)/.test(n)) return "health";
  if (/(exam|study|marks|grades|academic|school pressure|college pressure|university|fail|failing|result|tuition|assignment|syllabus|boards)/.test(n)) return "academic";
  if (/(relationship|marriage|divorce|separation|breakup|broke up|cheating|affair|my wife|my husband|wife|husband|my partner|my boyfriend|my girlfriend|love life|romantic|couple|spouse)/.test(n)) return "relationship";
  if (/(purpose|meaning|meaningless|identity|who am i|don't know who i am|lost myself|existential|direction|what should i do with|what's the point|my life has no|nothing makes sense)/.test(n)) return "identity";
  if (/(anger|angry|irritat|frustrat|rage|furious|mad at|cannot control my temper|losing my temper)/.test(n)) return "anger";
  if (/(fear|fearful|coward|scared|afraid|phobia|terrified)/.test(n)) return "fear";
  if (/(overconfiden|ego|reckless|arrogant|think i'm better|over.estimate)/.test(n)) return "overconfidence";
  if (/(stigma|shame|judged|looks|appearance|ugly|unattractive|not good looking|how i look|self.esteem|self.worth|self.image|insecure|my body|body image|fat|too thin|complexion|skin)/.test(n)) return "stigma";
  if (/(anxiety|anxious|panic|worry|worried|stress|stressed|overthinking|nervous wreck|pit in my stomach)/.test(n)) return "anxiety";
  if (/(burnout|burned out|exhaust|tired|drained|collapse|overworked|no energy|running on empty)/.test(n)) return "burnout";
  // Recognition / credit deficit — feeling unseen, uncredited at work or home
  if (/(due credit|not given credit|not get credit|credit for my|not credited|not given recognition|not given.*credit|credit.*not given|not given.*due|hardwork.*not|hard work.*not|hardworking.*not|efforts.*not appreciated|not appreciated.*effort|not appreciated by|not appreciated.*senior|not appreciated.*family|not appreciated.*office|not appreciated.*home|senior.*not appreci|family.*not appreci|not acknowledged|not recognized by|not recognised by|underappreciated|undervalued|overlook.*effort|my efforts.*not|my work.*not|my contribution.*not|not seen.*senior|not seen.*family|not seen.*office|no credit|no recognition|recognition.*not|not getting credit)/.test(n)) return "loneliness";
  if (/(lonely|loneliness|alone|isolated|ignored|invisible|unappreciated|not appreciated|not valued|not noticed|not recognised|not recognized|unwanted|rejected|unloved|worthless|no one cares|nobody cares|not seen)/.test(n)) return "loneliness";
  return null;
}

/**
 * Generates a short, personal acknowledgment of what the user shared.
 * This is shown as the counseling "heard" step before routing.
 * Supreme-level: covers all 17 issue dimensions.
 */
function buildCounselingAcknowledgment(text: string, issueId: IssueId, route: GuidedSupportRoute): { heard: string; nextStep: string } {
  const t = text.toLowerCase();

  // ── Positive / neutral check-in ─────────────────────────────────────────────
  // Guards against the "Default" branch at the bottom of this function ("Whatever
  // you are carrying right now is real...") firing on messages that describe no
  // distress at all, e.g. "I am feeling energetic". Checked first so it wins
  // over every distress branch below.
  if (isPositiveCheckIn(t)) {
    return buildPositiveCheckInReply(t);
  }

  // ── Grief / loss ────────────────────────────────────────────────────────────
  if (issueId === "grief" || /(grief|griev|mourning|bereaved|bereavement|lost someone|someone died|passed away|death of|loss of)/.test(t)) {
    return {
      heard: "Losing someone — or something that mattered deeply — leaves a gap that no words can fill. Grief is not something to fix; it is something to move through, at your own pace. I am glad you felt you could share this.",
      nextStep: "Opening a gentle space for you to process this and find support."
    };
  }

  // ── Trauma / abuse ──────────────────────────────────────────────────────────
  if (issueId === "trauma" || /(trauma|ptsd|flashback|abuse|abused|assault|assaulted|molested|domestic violence|childhood abuse)/.test(t)) {
    return {
      heard: "What you went through was real, and it was not your fault. Trauma stays in the body long after the event. The fact that you are talking about it is a meaningful step, and you deserve proper support.",
      nextStep: "Opening professional guidance and safe steps forward."
    };
  }

  // ── Addiction / compulsive behaviour ───────────────────────────────────────
  if (issueId === "addiction" || /(addict|addiction|alcoholic|drug|substance|gambling|can't stop drinking|can't stop using|compulsive|rehab)/.test(t)) {
    return {
      heard: "Recognising a compulsive pattern takes real honesty, and you have just done that. This is not about willpower — the brain literally changes under repeated use, and breaking free requires the right kind of help.",
      nextStep: "Opening recovery guidance and professional support pathways."
    };
  }

  // ── Parenting challenges ────────────────────────────────────────────────────
  if (issueId === "parenting" || /(my child|my son|my daughter|parenting|new parent|postpartum|toddler|teen behaviour)/.test(t)) {
    return {
      heard: "Parenting is one of the hardest jobs in existence, and the love you feel makes every difficulty twice as intense. Whatever you are navigating right now, you are not the first — and you do not have to figure it out alone.",
      nextStep: "Opening guidance specifically for your parenting situation."
    };
  }

  // ── Financial stress ────────────────────────────────────────────────────────
  if (issueId === "financial" || /(financial|money problem|debt|broke|bankrupt|loan|can't pay|rent|afford|lost my job|fired|unemployed)/.test(t)) {
    return {
      heard: "Financial pressure is one of the most visceral stresses a person can carry — it colours every other part of life. The anxiety, the shame, the sleeplessness — all of that is completely understandable. Let us look at this clearly together.",
      nextStep: "Opening your path to clarity, practical steps, and stress relief."
    };
  }

  // ── Health anxiety / physical illness ──────────────────────────────────────
  if (issueId === "health" || /(illness|chronic|diagnosis|diagnosed|cancer|heart|disease|disability|chronic pain|health anxiety|doctor said)/.test(t)) {
    return {
      heard: "Dealing with a health concern — whether it is your own body, or fear about it — can feel very isolating. The uncertainty is often the hardest part. You are right to take it seriously and to seek support alongside whatever medical care you are getting.",
      nextStep: "Opening guidance for your health situation and the emotional weight around it."
    };
  }

  // ── Academic pressure ───────────────────────────────────────────────────────
  if (issueId === "academic" || /(exam|study|marks|grades|academic pressure|fail|failing|result|boards|entrance|syllabus)/.test(t)) {
    return {
      heard: "Academic pressure can feel enormous — like your entire future is riding on a single number. That fear is real, but you are more than your results. Let us take this apart together and find the pressure points we can actually work on.",
      nextStep: "Opening focused guidance for your academic situation."
    };
  }

  // ── Relationship issues ─────────────────────────────────────────────────────
  if (issueId === "relationship" || /(relationship|marriage|divorce|separation|breakup|cheating|affair|my wife|my husband|wife|husband|my partner|my boyfriend|my girlfriend|love life)/.test(t)) {
    return {
      heard: "Relationship pain — whether it is distance, betrayal, loss, or conflict — touches something deep in who we are. You gave something of yourself, and right now that feels uncertain or broken. That deserves careful attention.",
      nextStep: "Opening your relationship guidance path."
    };
  }

  // ── Identity and purpose ────────────────────────────────────────────────────
  if (issueId === "identity" || /(purpose|meaning|meaningless|identity|who am i|lost myself|existential|what should i do with my life|what's the point)/.test(t)) {
    return {
      heard: "Feeling lost about who you are or where you are headed is one of the most unsettling places a person can be. It is also one of the most important questions to sit with. The fact that you are asking it means something important is shifting.",
      nextStep: "Opening your path to clarity and direction."
    };
  }

  // ── Self-esteem / looks / body image ────────────────────────────────────────
  if (issueId === "stigma" || /(looks|appearance|ugly|unattractive|not good looking|how i look|self.esteem|self.worth|self.image|body image|my body|fat|skin|complexion)/.test(t)) {
    return {
      heard: "The way we feel about how we look can quietly drain our confidence in everything else. That inner critic is loud, and often very unfair. What you are carrying is real, and it deserves to be addressed — not dismissed.",
      nextStep: "Opening your calm and self-worth guidance path."
    };
  }

  // ── Unappreciated / recognition deficit — dual work + home context ───────────
  if (/(unappreciated|not appreciated|not valued|not noticed|ignored|not recognised|not recognized|no one cares|effort.*not|hard work.*not|hardwork.*not|not seen|due credit|not given credit|not given.*credit|not credited|not acknowledged|not given recognition|credit.*not given|underappreciated|undervalued|not appreciated by|not recognized by|not recognised by|my contribution|my efforts.*not|my work.*not|overlook.*effort|no credit|no recognition)/.test(t)) {
    const atWork = /(work|office|senior|boss|manager|colleague|job|workplace|career)/.test(t);
    const atHome = /(home|wife|husband|family|spouse|partner|parent|children|kids|relatives|sibling)/.test(t);
    if (atWork && atHome) {
      return {
        heard: "Not being seen — neither at work nor at home — cuts at you from two directions at once. When the people you report to and the people you live with both miss your effort, it creates a loneliness that is very hard to put into words. That feeling is real, valid, and it matters.",
        nextStep: "Opening your personal path to address both of these."
      };
    }
    if (atWork) {
      return {
        heard: "Putting in genuine effort and having it go unnoticed by the people you work with or answer to is genuinely demoralising. Your contribution has value whether or not it is being acknowledged right now.",
        nextStep: "Opening guidance for the recognition gap at work."
      };
    }
    if (atHome) {
      return {
        heard: "When the people you share your home and life with do not seem to notice what you give, it creates a loneliness that sits right in the middle of your daily life. You deserve to feel seen and appreciated at home.",
        nextStep: "Opening guidance for the home dimension of this."
      };
    }
    return {
      heard: "Feeling unseen and unappreciated after genuine effort is one of the most isolating feelings there is. What you bring matters, even when no one is saying so.",
      nextStep: "Opening your guidance path to work through this."
    };
  }

  // ── Loneliness / isolation / rejected ───────────────────────────────────────
  if (issueId === "loneliness" || /(lonely|loneliness|alone|isolated|invisible|unwanted|rejected|unloved|worthless|no one|nobody)/.test(t)) {
    return {
      heard: "Feeling invisible or disconnected is one of the deepest pains a person can carry — especially when you are surrounded by people and still feel alone. You are not invisible to me. What you are going through matters.",
      nextStep: "Opening your calm and connection path."
    };
  }

  // ── Anger / rage ────────────────────────────────────────────────────────────
  if (issueId === "anger" || /(angry|anger|rage|furious|irritat|frustrat|mad at|losing my temper)/.test(t)) {
    return {
      heard: "That anger is signalling something important — a need that is not being met, or something that feels deeply unfair. Before it turns outward in ways you may regret, let us find the real source underneath it.",
      nextStep: "Opening your calm route first to settle the heat."
    };
  }

  // ── Anxiety / panic / stress ─────────────────────────────────────────────────
  if (issueId === "anxiety" || /(anxious|anxiety|stress|stressed|overwhelmed|panic|worried|nervous|overthinking)/.test(t)) {
    return {
      heard: "When anxiety takes hold, it can feel like your mind is running scenarios you cannot stop. That is exhausting, and it can make even small things feel impossible. You do not have to manage this alone.",
      nextStep: "Opening your calm path to settle the pressure first."
    };
  }

  // ── Burnout / exhaustion ─────────────────────────────────────────────────────
  if (issueId === "burnout" || /(burnout|burned out|exhaust|tired|drained|collapse|no energy|running on empty)/.test(t)) {
    return {
      heard: "Burnout is not weakness — it is what happens when someone keeps giving without enough coming back. Your body and mind are sending a clear message. You need rest and recovery, not more advice to push harder.",
      nextStep: "Opening your rest and recovery path."
    };
  }

  // ── Fear / phobia ────────────────────────────────────────────────────────────
  if (issueId === "fear" || /(fear|fearful|coward|scared|afraid|terrified|phobia)/.test(t)) {
    return {
      heard: "Fear is not cowardice — it is your system trying to protect you. The question is whether what you fear is truly dangerous, or whether your mind has learned to see danger where there is only difficulty. Let us look at this together.",
      nextStep: "Opening your calm and courage guidance path."
    };
  }

  // ── Shame / stigma ───────────────────────────────────────────────────────────
  if (/(shame|stigma|embarrass|judged|judging|humiliated)/.test(t)) {
    return {
      heard: "Carrying shame or the fear of being judged takes an enormous amount of energy — and it often silences the very things that deserve to be heard. You deserve to put that weight down.",
      nextStep: "Opening guidance for working through this together."
    };
  }

  // ── Redress / complaint ──────────────────────────────────────────────────────
  if (route === "redress") {
    return {
      heard: "What you are describing sounds like something that needs to be properly addressed through the right channel. You have every right to take this forward, and there is a process that exists specifically for situations like yours.",
      nextStep: "Opening the formal guidance and redress path for you."
    };
  }

  // ── Default ──────────────────────────────────────────────────────────────────
  return {
    heard: "Whatever you are carrying right now is real, and it is worth taking seriously. I am here to listen first — to actually understand what is going on — before we look at what might help.",
    nextStep: "Opening your personal guidance path."
  };
}

function findGuidedSupportRedressRouteFromText(text: string): RedressRouteId {
  const normalized = text.toLowerCase();
  if (/(ragging|hostel|senior|junior|batch|fresher)/.test(normalized)) return "ragging";
  if (/(harass|sexual harassment|gender|women|female|stalk|posh|icc)/.test(normalized)) return "harassment";
  if (/(domestic violence|wife|husband|spouse|matrimonial|family abuse|in.laws|dowry|divorce)/.test(normalized)) return "domestic";
  if (/(loan|debt|emi|bank fraud|chit fund|financial fraud|money lender|interest|nbfc|rbi|banking ombudsman)/.test(normalized)) return "financial";
  if (/(salary|unfair dismissal|pf|epfo|labour|workplace rights|termination|bonus|overtime|contract|hr)/.test(normalized)) return "workplace";
  if (/(police|crime|assault|threat|blackmail|cyber crime|violence|kidnap|extortion)/.test(normalized)) return "crime";
  if (/(office|company|firm|factory|manager|job|bank|private school|private college)/.test(normalized)) return "private";
  if (/(government|officer|department|public|official|cpgrams)/.test(normalized)) return "public";
  return "academic";
}

function inferIdentityIdFromText(text: string, fallback: IdentityId = "other"): IdentityId {
  const normalized = text.toLowerCase();
  if (/(student|school|college|university|exam|class|assignment|homework|study)/.test(normalized)) return "student";
  if (/(teacher|faculty|lecture|classroom|students?)/.test(normalized)) return "teacher";
  if (/(doctor|hospital|patient|clinic|medical)/.test(normalized)) return "doctor";
  if (/(nurse|ward|shift|care unit)/.test(normalized)) return "nurse";
  if (/(engineer|coding|developer|system|project|technical)/.test(normalized)) return "engineer";
  if (/(bank|banker|finance|loan|account|branch|transaction)/.test(normalized)) return "banker";
  if (/(lawyer|court|case|hearing|petition|legal)/.test(normalized)) return "lawyer";
  if (/(entrepreneur|startup|business|founder|client|sales)/.test(normalized)) return "entrepreneur";
  if (/(homemaker|household|home care|housework)/.test(normalized)) return "homemaker";
  if (/(parent|mother|father|son|daughter|child care|family)/.test(normalized)) return "parent";
  if (/(officer|police|army|force|duty|department)/.test(normalized)) return "officer";
  if (/(official|government|public service|public office)/.test(normalized)) return "official";
  if (/(caregiver|caretaker|supporting someone)/.test(normalized)) return "caregiver";
  if (/(retired|pension|old age)/.test(normalized)) return "retired";
  if (/(child|teen|teenager|minor)/.test(normalized)) return "child";
  if (/(professional|office worker|manager|employee|workplace)/.test(normalized)) return "professional";
  return fallback;
}

function createPrivateIntakeDraft(): PrivateIntakeDraft {
  return {
    overview: "",
    timelineContext: "",
    frequencyContext: "",
    currentFeeling: "",
    emotionIntensity: "",
    triggerContext: "",
    bodySignal: "",
    dailyImpactContext: "",
    supportNeed: "",
    supportPreferences: "",
    safetyNote: "",
    familyContext: "",
    relativeContext: "",
    friendsContext: "",
    coworkerContext: "",
    behaviorPattern: "",
    previousAttempts: "",
    neededOutcome: "",
    strengthsContext: "",
    privacyBoundary: ""
  };
}

function normalizePrivateIntakeDraft(value: unknown): PrivateIntakeDraft {
  if (!value || typeof value !== "object") return createPrivateIntakeDraft();
  const draft = value as Partial<PrivateIntakeDraft>;
  return {
    overview: typeof draft.overview === "string" ? draft.overview.slice(0, 1200) : "",
    timelineContext: typeof draft.timelineContext === "string" ? draft.timelineContext.slice(0, 700) : "",
    frequencyContext: typeof draft.frequencyContext === "string" ? draft.frequencyContext.slice(0, 500) : "",
    currentFeeling: typeof draft.currentFeeling === "string" ? draft.currentFeeling.slice(0, 300) : "",
    emotionIntensity: typeof draft.emotionIntensity === "string" ? draft.emotionIntensity.slice(0, 120) : "",
    triggerContext: typeof draft.triggerContext === "string" ? draft.triggerContext.slice(0, 900) : "",
    bodySignal: typeof draft.bodySignal === "string" ? draft.bodySignal.slice(0, 900) : "",
    dailyImpactContext: typeof draft.dailyImpactContext === "string" ? draft.dailyImpactContext.slice(0, 900) : "",
    supportNeed: typeof draft.supportNeed === "string" ? draft.supportNeed.slice(0, 900) : "",
    supportPreferences: typeof draft.supportPreferences === "string" ? draft.supportPreferences.slice(0, 700) : "",
    safetyNote: typeof draft.safetyNote === "string" ? draft.safetyNote.slice(0, 500) : "",
    familyContext: typeof draft.familyContext === "string" ? draft.familyContext.slice(0, 900) : "",
    relativeContext: typeof draft.relativeContext === "string" ? draft.relativeContext.slice(0, 900) : "",
    friendsContext: typeof draft.friendsContext === "string" ? draft.friendsContext.slice(0, 900) : "",
    coworkerContext: typeof draft.coworkerContext === "string" ? draft.coworkerContext.slice(0, 900) : "",
    behaviorPattern: typeof draft.behaviorPattern === "string" ? draft.behaviorPattern.slice(0, 1200) : "",
    previousAttempts: typeof draft.previousAttempts === "string" ? draft.previousAttempts.slice(0, 900) : "",
    neededOutcome: typeof draft.neededOutcome === "string" ? draft.neededOutcome.slice(0, 900) : "",
    strengthsContext: typeof draft.strengthsContext === "string" ? draft.strengthsContext.slice(0, 700) : "",
    privacyBoundary: typeof draft.privacyBoundary === "string" ? draft.privacyBoundary.slice(0, 700) : ""
  };
}

