  wealth: { Ketu: -0.8, Shukra: 1.2, Surya: 0.8, Chandra: 0.2, Mangal: 0.2, Rahu: 0.8, Guru: 1.2, Shani: 0.6, Budha: 1.0 },
  peace: { Ketu: 0.2, Shukra: 1.0, Surya: 0.0, Chandra: 1.4, Mangal: -1.2, Rahu: -1.4, Guru: 1.2, Shani: -1.4, Budha: 0.6 },
