function getMoonChartPlanetCategoryScore(planet: string | null | undefined, category: MoonChart48Category): number {
  if (!planet) return 0;
  return PLANET_MOON_CHART_STRENGTH[planet]?.[category] ?? 0;
}

function getMoonChartHouseScore(category: MoonChart48Category, house: number): number {
  const specific = HOUSE_MOON_CHART_STRENGTH[category]?.[house];
  if (typeof specific === "number") return specific;
  if (house === 1 || house === 5 || house === 9) return 4;
  if (house === 4 || house === 7 || house === 10) return 3;
  if (house === 3 || house === 6 || house === 11) return 2;
  if (house === 8 || house === 12) return -4;
  return 0;
}

function describeMoonChartScore(score: number, category: MoonChart48Category, lang: "en" | "hi" = "en"): string {
  const categoryFocus: Record<MoonChart48Category, string> = {
    self: "identity and confidence",
    mind: "mental and emotional steadiness",
    body: "body rhythm and routine",
    relationship: "bonding, trust, and communication",
    work: "duty, visibility, and execution",
    money: "resources, saving, and obligations",
    family: "home, speech, and nurturance",
    spiritual: "faith, release, and dharma",
    risk: "caution, hidden pressure, and restraint",
    growth: "learning, courage, and future direction",
  };
  const categoryFocusHi: Record<MoonChart48Category, string> = {
    self: "पहचान और आत्मविश्वास",
    mind: "मानसिक और भावनात्मक स्थिरता",
    body: "शरीर की लय और दिनचर्या",
    relationship: "जुड़ाव, विश्वास और संवाद",
    work: "कर्तव्य, दृश्यता और निष्पादन",
    money: "संसाधन, बचत और दायित्व",
    family: "घर, वाणी और पोषण",
    spiritual: "आस्था, मुक्ति और धर्म",
    risk: "सावधानी, छुपा दबाव और संयम",
    growth: "सीख, साहस और भविष्य की दिशा",
  };
  if (lang === "hi") {
    const f = categoryFocusHi[category];
    if (score >= 82) return `${f} को प्रबल सहयोग मिल रहा है`;
    if (score >= 68) return `${f} स्थिर चुनावों के साथ संभव है`;
    if (score >= 50) return `${f} को संतुलन और समय चाहिए`;
    return `${f} को अतिरिक्त सावधानी और स्थिरता चाहिए`;
  }
  if (score >= 82) return `${categoryFocus[category]} are strongly supported`;
  if (score >= 68) return `${categoryFocus[category]} are workable with steady choices`;
  if (score >= 50) return `${categoryFocus[category]} need balance and timing`;
  return `${categoryFocus[category]} need extra caution and grounding`;
}

function buildMoonChartMultidimensionalEngine(input: {
  rashiId: number;
  janmaNakshatra: ReturnType<typeof getJanmaNakshatra>;
  dashaState: VimshottariDashaState | null;
  tithi: ReturnType<typeof getTodayTithi>;
  vara: typeof VARA_INFO[0];
  // Accepted for backward-compatible callers and chart display only. It is
  // intentionally excluded from prediction/remedy scoring: all guidance in
  // this engine is calculated solely from the Moon chart, as promised in the
  // product's methodology note.
  lagnaId?: number | null;
  // When "hi", the whole reading (blueprint label/meaning, interpretation,
  // score reason, remedy, prediction, verdict word) is produced in Hindi.
  // Defaults to "en" so every existing caller (counselling insight system, Path
  // complement, Insights) is unchanged -- only the chart-facing display and
  // Ask-the-chart pass "hi" when the user's chartBriefLang is Hindi.
  lang?: "en" | "hi";
}): MoonChart48Reading[] {
  const lang: "en" | "hi" = input.lang ?? "en";
  const rashi = VEDIC_RASHIS[input.rashiId] ?? VEDIC_RASHIS[0];
  const nakshatra = input.janmaNakshatra;
  const nakshatraId = nakshatra?.id ?? 0;
  const nakshatraLord = nakshatra?.lord ?? "Chandra";
  const pada = nakshatra?.pada ?? 1;
  const degreesInNakshatra = nakshatra?.degreesInNakshatra ?? 0;
  const lunarFinePulse = ((degreesInNakshatra / DEG_PER_NAKSHATRA) - 0.5) * 10;
  const tithiNumber = input.tithi?.number ?? 1;
  const tithiBalance = tithiNumber === 11 ? 5 : tithiNumber === 4 || tithiNumber === 8 || tithiNumber === 14 ? -4 : tithiNumber <= 5 ? 2 : 0;
  const varaPlanet = input.vara?.planet?.split(" ")[0] ?? "Chandra";
  const maha = input.dashaState?.currentMahadasha ?? nakshatraLord;
  const antar = input.dashaState?.currentAntardasha ?? nakshatraLord;

  return MOON_CHART_48_BLUEPRINTS.map((dimensionEn, index) => {
    // Swap in the Hindi label/meaning/remedyFocus for this blueprint when in
    // Hindi mode; everything numeric (category/house/weight) stays shared.
    const hiText = lang === "hi" ? MOON_CHART_48_BLUEPRINT_HI[dimensionEn.id] : null;
    const dimension = hiText ? { ...dimensionEn, ...hiText } : dimensionEn;
    const houseScore = getMoonChartHouseScore(dimension.category, dimension.house);
    const mahaScore = getMoonChartPlanetCategoryScore(maha, dimension.category);
    const antarScore = getMoonChartPlanetCategoryScore(antar, dimension.category);
    const nakshatraScore = getMoonChartPlanetCategoryScore(nakshatraLord, dimension.category);
    const varaScore = getMoonChartPlanetCategoryScore(varaPlanet, dimension.category) * 0.25;
    const padaStability = pada === 2 || pada === 3 ? 2 : 0;
    const moonSignElementBias =
      rashi.element.includes("Jal") && (dimension.category === "mind" || dimension.category === "family" || dimension.category === "spiritual") ? 3 :
      rashi.element.includes("Agni") && (dimension.category === "self" || dimension.category === "work" || dimension.category === "growth") ? 3 :
      rashi.element.includes("Prithvi") && (dimension.category === "body" || dimension.category === "money" || dimension.category === "family") ? 3 :
      rashi.element.includes("Vayu") && (dimension.category === "relationship" || dimension.category === "growth" || dimension.category === "work") ? 3 : 0;

    const raw = 60
      + houseScore * 1.55
      + mahaScore * 0.85
      + antarScore * 0.65
      + nakshatraScore * 0.4
      + varaScore
      + moonSignElementBias
      + tithiBalance
      + lunarFinePulse * 0.35
      + ((nakshatraId + index) % 3 - 1) * dimension.weight;

    const score = clampMoonScore(raw);
    const verdict = moonChartVerdict(score);
    const focus = describeMoonChartScore(score, dimension.category, lang);
    const dashaText = input.dashaState
      ? (lang === "hi" ? `${maha} महादशा / ${antar} अंतर्दशा` : `${maha} Mahadasha / ${antar} Antardasha`)
      : (lang === "hi" ? `${nakshatraLord} नक्षत्र-स्वामी चरण` : `${nakshatraLord} Nakshatra-lord phase`);
    // The category-level pack (title + generic steps) is shared by every
    // blueprint in the same category on purpose -- it names a real technique
    // (e.g. "Pause before escalation") -- but its first generic step is
    // replaced with this blueprint's own remedyFocus so two life-areas in
    // the same category (e.g. "Hidden fears" and "Legal conflicts", both
    // category "risk") no longer render identical steps end to end. Same
    // fix philosophy as the interpretation/meaning dedup above.
    const categoryPack = moonChartCategoryRemedyPack(dimension.category, rashi.name, lang);
    const remedyPack = { title: categoryPack.title, steps: [dimension.remedyFocus, ...categoryPack.steps.slice(1)] };
    const scoreReason = buildMoonChartScoreReason({
      houseScore,
      mahaScore,
      antarScore,
      nakshatraScore,
      varaScore,
      tithiBalance,
      moonSignElementBias,
      lunarFinePulse: lunarFinePulse * 0.35,
      house: dimension.house,
      category: dimension.category,
      maha,
      antar,
      nakshatraLord,
      varaPlanet,
      lagnaRashiName: null,
      lagnaLord: null,
      lagnaLordScore: 0,
      lagnaElementBias: 0,
      lang,
    });
    // dimension.label/meaning are already Hindi in Hindi mode (see hiText
    // swap above). Proper nouns (Rashi/Nakshatra names, Tithi/Vara) stay in
    // their standard Sanskrit/Devanagari form; vara uses its .hi field in
    // Hindi so the day-name reads naturally.
    const varaName = lang === "hi" ? input.vara.hi : input.vara.en;
    const interpretation = lang === "hi"
      ? `सरल भाषा में, ${dimension.label} का संबंध इससे है: ${dimension.meaning}। ${moonChartVerdictTone(verdict, "hi")}`
      : `In plain language, ${dimension.label.toLowerCase()} belongs to ${dimension.meaning}. ${moonChartVerdictTone(verdict)}`;

    return {
      ...dimension,
      score,
      verdict,
      verdictLabel: moonChartVerdictLabel(verdict, lang),
      prediction: lang === "hi"
        ? `चंद्र राशि ${rashi.name}${nakshatra ? `, ${nakshatra.name} नक्षत्र पाद ${pada}` : ""} से, ${dimension.label} आज ${focus}। यह पठन केवल चंद्र-भाव ${dimension.house}, ${dashaText}, ${input.tithi.name} ${input.tithi.paksha}, और ${varaName} के माध्यम से गणना किया गया है।`
        : `From Moon Rashi ${rashi.name}${nakshatra ? `, ${nakshatra.name} Nakshatra pada ${pada}` : ""}, ${dimension.label.toLowerCase()} shows ${focus} today. This reading is calculated solely through Moon-house ${dimension.house}, ${dashaText}, ${input.tithi.name} ${input.tithi.paksha}, and ${input.vara.en}.`,
      interpretation,
      scoreReason,
      remedy: lang === "hi" ? `चंद्र-चार्ट उपाय: ${remedyPack.steps.join(" ")}` : `Moon-chart remedy: ${remedyPack.steps.join(" ")}`,
      remedyTitle: remedyPack.title,
      remedySteps: remedyPack.steps,
      calculationBasis: lang === "hi"
        ? `केवल चंद्र-चार्ट आधार: सायडरियल चंद्र ${nakshatra?.siderealMoonLongitude.toFixed(2) ?? "उपलब्ध नहीं"}°; जन्म राशि ${rashi.name}; नक्षत्र ${nakshatra?.name ?? "अनुमानित"}; पाद ${pada}; चंद्र से भाव ${dimension.house}; दशा ${maha}/${antar}; तिथि ${input.tithi.number}।`
        : `Moon-chart-only basis: sidereal Moon ${nakshatra?.siderealMoonLongitude.toFixed(2) ?? "n/a"}°; Janma Rashi ${rashi.name}; Nakshatra ${nakshatra?.name ?? "approximated"}; pada ${pada}; house ${dimension.house} from Moon; dasha ${maha}/${antar}; tithi ${input.tithi.number}.`,
      visualAngle: (index % 12) * 30,
      visualDepth: Math.max(0.12, Math.min(1, score / 100)),
    };
  });
}

function summarizeMoonChart48(readings: MoonChart48Reading[]): { top: MoonChart48Reading[]; careful: MoonChart48Reading[]; average: number } {
  const sorted = [...readings].sort((a, b) => b.score - a.score);
  const careful = [...readings].sort((a, b) => a.score - b.score).slice(0, 4);
  const average = readings.length ? Math.round(readings.reduce((sum, item) => sum + item.score, 0) / readings.length) : 0;
  return { top: sorted.slice(0, 6), careful, average };
}

// ── Error Boundary ─────────────────────────────────────────────────────────
class AppErrorBoundary extends React.Component<
  { children: React.ReactNode },
  { hasError: boolean; errorMessage: string }
> {
  constructor(props: { children: React.ReactNode }) {
    super(props);
    this.state = { hasError: false, errorMessage: "" };
  }
  static getDerivedStateFromError(error: Error) {
    return { hasError: true, errorMessage: error?.message ?? "Unknown error" };
  }
  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error("[AethonBeacon] Render error:", error, info);
  }
  render() {
    if (this.state.hasError) {
      return (
        <View style={{ flex: 1, backgroundColor: "#FFFFFF", alignItems: "center", justifyContent: "center", padding: 32 }}>
          <Text style={{ fontSize: 40, marginBottom: 16 }}>⚠️</Text>
          <Text style={{ color: "#0A6F66", fontSize: 18, fontWeight: "700", marginBottom: 8, textAlign: "center" }}>
            Something went wrong
          </Text>
          <Text style={{ color: "#263244", fontSize: 14, textAlign: "center", marginBottom: 24, lineHeight: 20 }}>
            NAYIQ hit an unexpected error. Your data is safe — restart the app to continue.
          </Text>
          <Text style={{ color: "#1F2937", fontSize: 12, textAlign: "center", fontFamily: "monospace" }}>
            {this.state.errorMessage}
          </Text>
        </View>
      );
    }
    return this.props.children;
  }
}

// ── Per-tab error boundary — isolates crashes to a single tab ─────────────
class TabErrorBoundary extends React.Component<
  { children: React.ReactNode; tabName: string; languageId?: LanguageId },
  { hasError: boolean }
> {
  constructor(props: { children: React.ReactNode; tabName: string; languageId?: LanguageId }) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error(`[AethonBeacon] Tab "${this.props.tabName}" crashed:`, error, info);
  }
  render() {
    if (this.state.hasError) {
      const languageId = this.props.languageId ?? "english";
      const l = (english: string, translations?: Partial<Record<LanguageId, string>>) =>
        pickLocalizedText(languageId, { english, ...(translations ?? {}) });
      return (
        <View style={{ flex: 1, alignItems: "center", justifyContent: "center", padding: 32, backgroundColor: "#FFFFFF" }}>
          <Text style={{ fontSize: 32, marginBottom: 12 }}>⚠️</Text>
          <Text style={{ color: "#0A6F66", fontSize: 16, fontWeight: "700", marginBottom: 8, textAlign: "center" }}>
            {l("This section had an issue", { hindi: "इस अनुभाग में समस्या आई", telugu: "ఈ విభాగంలో సమస్య వచ్చింది", tamil: "இந்தப் பகுதியில் ஒரு சிக்கல் ஏற்பட்டது", urdu: "اس حصے میں مسئلہ پیش آیا" })}
          </Text>
          <Text style={{ color: "#263244", fontSize: 13, textAlign: "center", lineHeight: 20 }}>
            {l("Your data is safe. Switch to another tab and come back to refresh this section.", {
              hindi: "आपका डेटा सुरक्षित है। किसी अन्य टैब पर जाएँ और वापस आकर इस अनुभाग को रीफ़्रेश करें।",
              telugu: "మీ డేటా సురక్షితం. మరో ట్యాబ్‌కి వెళ్లి తిరిగి వచ్చి ఈ విభాగాన్ని రిఫ్రెష్ చేయండి.",
              tamil: "உங்கள் தரவு பாதுகாப்பாக உள்ளது. வேறு ஒரு tab-க்கு சென்று மீண்டும் வந்து இந்தப் பகுதியை refresh செய்யவும்.",
              urdu: "آپ کا ڈیٹا محفوظ ہے۔ کسی دوسرے tab پر جائیں اور واپس آکر اس حصے کو refresh کریں۔"
            })}
          </Text>
          <Pressable
            onPress={() => this.setState({ hasError: false })}
            style={{ marginTop: 20, backgroundColor: "#DEEAF2", borderRadius: 10, paddingHorizontal: 20, paddingVertical: 10 }}
            accessibilityRole="button"
          >
            <Text style={{ color: "#0A6F66", fontSize: 13, fontWeight: "700" }}>{l("Try again", { hindi: "फिर कोशिश करें", telugu: "మళ్లీ ప్రయత్నించండి", tamil: "மீண்டும் முயற்சிக்கவும்", urdu: "دوبارہ کوشش کریں" })}</Text>
          </Pressable>
        </View>
      );
    }
    return this.props.children;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// EXIT REPORT ENGINE
// ─────────────────────────────────────────────────────────────────────────────

type SessionEvent = {
  type: "tab_visit" | "issue_detected" | "guidance_viewed" | "checkin" | "counseling_turn" | "journal_written" | "horoscope_viewed" | "birth_chart_viewed" | "meditation" | "community";
  label: string;
  detail?: string;
  ts: number;
};

type DailyVisitReport = {
  userName: string;
  sessionDurationMins: number;
  tabsVisited: string[];
  issuesDetected: string[];
  guidanceTopics: string[];
  checkInsLogged: number;
  counselingTurns: number;
  journalWritten: boolean;
  moodScore: number | null;
  moodLabel: string | null;
  strengths: string[];
  focusAreas: string[];
  tomorrowRecommendations: string[];
  overallSummary: string;
  generatedAt: string;
};

const EXIT_REPORT_ISSUE_LABELS: Record<string, string> = {
  general: "General wellbeing",
  anger: "Anger & frustration",
  anxiety: "Anxiety & worry",
  fear: "Fear & phobias",
  overconfidence: "Overconfidence",
  stigma: "Social stigma",
  burnout: "Burnout & exhaustion",
  loneliness: "Loneliness & isolation",
  grief: "Grief & loss",
  identity: "Identity & self-worth",
  health: "Health concerns",
  financial: "Financial stress",
  relationship: "Relationship issues",
  parenting: "Parenting challenges",
  trauma: "Trauma & PTSD",
  academic: "Academic pressure",
  addiction: "Addiction & habits",
};

function generateDailyVisitReport(
  userName: string,
  sessionStartTs: number,
  events: SessionEvent[],
  issueGuideId: string,
  entries: { score: number; toneLabel: string }[],
): DailyVisitReport {
  const now = Date.now();
  const durationMins = Math.max(1, Math.round((now - sessionStartTs) / 60000));

  // Deduplicate tab visits
  const tabsVisited = [...new Set(
    events.filter(e => e.type === "tab_visit").map(e => e.label)
  )];

  // Issues detected this session
  const issueEvents = events.filter(e => e.type === "issue_detected");
  const issuesDetected = [...new Set(
    issueEvents.map(e => EXIT_REPORT_ISSUE_LABELS[e.label] ?? e.label)
  )];
  if (issuesDetected.length === 0 && issueGuideId !== "general") {
    issuesDetected.push(EXIT_REPORT_ISSUE_LABELS[issueGuideId] ?? issueGuideId);
  }

  // Guidance topics
  const guidanceTopics = [...new Set(
    events.filter(e => e.type === "guidance_viewed").map(e => e.label)
  )];

  // Check-ins
  const checkInsLogged = events.filter(e => e.type === "checkin").length;

  // Counseling
  const counselingTurns = events.filter(e => e.type === "counseling_turn").length;

  // Journal
  const journalWritten = events.some(e => e.type === "journal_written");

  // Mood from today's entries. Callers are expected to pre-filter `entries`
  // down to today's check-ins before calling this function (both call sites
  // do this via createdAt); this function trusts that contract rather than
  // re-filtering, since its parameter type doesn't carry a date field.
  const todayEntries = entries;
  const avgScore = todayEntries.length > 0
    ? Math.round(todayEntries.reduce((s, e) => s + e.score, 0) / todayEntries.length)
    : null;
  const latestToneLabel = todayEntries[0]?.toneLabel ?? null;

  // Strengths from activities
  const strengths: string[] = [];
  if (checkInsLogged > 0) strengths.push("Self-awareness check-in completed");
  if (journalWritten) strengths.push("Reflective journaling practiced");
  if (counselingTurns > 0) strengths.push("Engaged in guided counseling");
  if (tabsVisited.includes("Meditation")) strengths.push("Meditation session started");
  if (tabsVisited.includes("Community")) strengths.push("Community connection explored");
  if (tabsVisited.includes("Guidance")) strengths.push("Guidance path explored");
  if (tabsVisited.includes("Tones")) strengths.push("Sound healing tones practiced");
  if (tabsVisited.includes("Vedic / Horoscope")) strengths.push("Vedic insight checked");
  if (strengths.length === 0) strengths.push("Showed up for your mental health today");

  // Focus areas
  const focusAreas: string[] = [];
  if (issuesDetected.length > 0) focusAreas.push(...issuesDetected.slice(0, 3));
  if (focusAreas.length === 0) focusAreas.push("General wellbeing maintenance");

  // Tomorrow's recommendations
  const recs: string[] = [];
  if (checkInsLogged === 0) recs.push("Log a mood check-in tomorrow to track your emotional baseline");
  if (!journalWritten) recs.push("Try a 5-minute journal entry — even 3 sentences helps");
  if (counselingTurns === 0) recs.push("Explore the guided counseling session for deeper insight");
  if (avgScore !== null && avgScore < 4) recs.push("Practice the breathing or calm-tone exercises to ease tension");
  if (tabsVisited.length < 3) recs.push("Explore the Wisdom or Community tabs for fresh perspective");
  recs.push("Keep your streak alive — consistency is where transformation happens");

  // Summary
  const activityCount = tabsVisited.length + (checkInsLogged > 0 ? 1 : 0) + (journalWritten ? 1 : 0) + (counselingTurns > 0 ? 1 : 0);
  const moodPhrase = avgScore !== null
    ? `Your mood registered at ${avgScore}/7 (${latestToneLabel ?? "balanced"})`
    : "No mood score logged";
  const issuePhrase = issuesDetected.length > 0
    ? `Key focus: ${issuesDetected.slice(0, 2).join(" & ")}`
    : "General wellbeing maintained";

  const overallSummary =
    `You spent ${durationMins} minute${durationMins !== 1 ? "s" : ""} with NAYIQ today. ` +
    `${moodPhrase}. ${issuePhrase}. ` +
    `${activityCount} activit${activityCount !== 1 ? "ies" : "y"} completed across ${tabsVisited.length || 1} section${tabsVisited.length !== 1 ? "s" : ""}. ` +
    `${strengths[0] ?? "Well done for showing up"}.`;

  return {
    userName,
    sessionDurationMins: durationMins,
    tabsVisited,
    issuesDetected,
    guidanceTopics,
    checkInsLogged,
    counselingTurns,
    journalWritten,
    moodScore: avgScore,
    moodLabel: latestToneLabel,
    strengths,
    focusAreas,
    tomorrowRecommendations: recs.slice(0, 4),
    overallSummary,
    generatedAt: new Date().toLocaleString("en-IN", { dateStyle: "full", timeStyle: "short" }),
  };
}

