// ── Persistent Bottom Navigation Bar ──────────────────────────────────────────
// 5 primary tabs always visible.
// Primary nav: Today / Journal / Calm Reset / Help / Profile
// Help and Redress is intentionally surfaced here (not buried in Pages) because
// safety, SOS, complaint route, and immediate support must be one tap away and visibly
// above the lower-priority "other/general" surfaces. Patterns, Community,
// Explore, Birth Chart, Practice, and Tones remain accessible via Pages.
const PRIMARY_NAV_TABS: Array<{ id: TabId | "more"; label: string; icon: string }> = [
  { id: "today",      label: "Today",      icon: "🏠" },
  { id: "journal",    label: "Journal",    icon: "✍️" },
  { id: "focus",      label: "Calm",       icon: "🪷" },
  { id: "redress",    label: "Help",       icon: "🛡️" },
  { id: "settings",   label: "Profile",    icon: "👤" },
];

// ─────────────────────────────────────────────────────────────────────────────
// COUNSELING ENGINE — multi-turn empathetic conversation before routing
// ─────────────────────────────────────────────────────────────────────────────

type CounselingStage = "listening" | "questioning" | "synthesizing" | "done";

interface CounselingTurn {
  role: "friend" | "user";
  message: string;
  // ISO timestamp of when the turn was created. Optional so any older
  // persisted/loaded session without it still renders (the bubble just omits
  // the time). New turns always set it -- see the four construction sites.
  ts?: string;
}

interface JourneyStep {
  tabId: TabId;
  label: string;
  emoji: string;
  reason: string;
  completed: boolean;
  skipped: boolean;
}

interface CounselingSession {
  stage: CounselingStage;
  originalIssue: string;
  turns: CounselingTurn[];
  questionIndex: number;
  detectedThemes: SupportDimensionId[];
  journeySteps: JourneyStep[];
}

function detectThemes(text: string): SupportDimensionId[] {
  const t = text.toLowerCase();
  const themes: SupportDimensionId[] = [];

  // Self-image / body / appearance / self-worth
  if (/(look|appear|ugly|unattractive|body image|my body|face|skin|complexion|fat|weight|how i look|self.esteem|self.worth|self.image|self.confidence|insecur|ashamed|embarrassed|not good looking)/.test(t)) themes.push("self-image");

  // Grief / loss
  if (/(grief|griev|mourn|bereaved|bereavement|lost someone|someone died|passed away|death of|loss of|they died|she died|he died|miss them|miss him|miss her)/.test(t)) themes.push("grief");

  // Trauma / abuse
  if (/(trauma|ptsd|flashback|abuse|abused|assault|assaulted|molested|domestic violence|childhood abuse|violated|sexual harassment|rape)/.test(t)) themes.push("trauma");

  // Addiction / compulsion
  if (/(addict|addiction|alcoholic|alcohol problem|drug|substance abuse|gambling|can't stop drinking|can't stop using|compulsive|habit|cravings|rehab|detox)/.test(t)) themes.push("addiction");

  // Academic pressure
  if (/(exam|study|marks|grades|academic|school pressure|college pressure|university|fail|failing|result|boards|entrance test|tuition|syllabus|assignment)/.test(t)) themes.push("academic");

  // Financial stress
  if (/(financial|money problem|debt|broke|bankrupt|loan|can't pay|rent|afford|salary cut|lost my job|job loss|fired|laid off|redundant|unemployed|expenses)/.test(t)) themes.push("financial");

  // Health / illness
  if (/(illness|sick|chronic|diagnosis|diagnosed|cancer|heart|disease|disability|chronic pain|medical|health anxiety|doctor said|hospital|treatment|medication)/.test(t)) themes.push("health");

  // Parenting
  if (/(my child|my son|my daughter|my kids|my baby|parenting|new parent|postpartum|toddler|teenager|teen behaviour|child behaviour|raising kids)/.test(t)) themes.push("parenting");

  // Relationship / romantic
  if (/(relationship|marriage|divorce|separation|breakup|broke up|cheating|affair|my wife|my husband|wife|husband|my partner|my boyfriend|my girlfriend|love life|romantic|couple|trust issues|infidelity)/.test(t)) themes.push("relationship");

  // Unappreciated / invisible / recognition deficit
  if (/(ignor|unappreciat|not valued|not noticed|not seen|invisible|unwanted|no one cares|nobody cares|not recognised|not recognized|not appreciated|efforts not|work not recognized|taken for granted|overlooked|due credit|not given credit|not credited|not acknowledged|not given recognition|credit.*not|hardwork.*not|underappreciated|undervalued|no credit|no recognition|not appreciated by|my contribution.*not|my efforts.*not)/.test(t)) themes.push("unappreciated");

  // Work / career
  if (/(work|office|senior|boss|manager|colleague|job|workplace|career|promotion|salary|professional)/.test(t)) themes.push("work");

  // Home / family
  if (/(home|wife|husband|family|spouse|partner|parent|children|kids|relatives|sibling|brother|sister|in.law|household)/.test(t)) themes.push("home-family");

  // Anger
  if (/(anger|angry|rage|furious|irritat|frustrat|mad|temper|losing it|hot.headed)/.test(t)) themes.push("anger");

  // Anxiety / panic / stress
  if (/(anxious|anxiety|worry|stressed|overwhelmed|panic|nervous|overthinking|racing thoughts|pit in my stomach|can't relax)/.test(t)) themes.push("anxiety");

  // Sadness / depression
  if (/(sad|depress|hopeless|numb|empty|hollow|low mood|no joy|can't feel anything|nothing matters|pointless)/.test(t)) themes.push("sadness");

  // Burnout / exhaustion
  if (/(burnout|exhaust|tired|drain|collapse|overworked|no energy|running on empty|depleted|too much)/.test(t)) themes.push("burnout");

  // Loneliness / isolation
  if (/(lonely|alone|isolated|no friend|no one to talk|cut off|disconnected|left out|no one listens|feel alone|completely alone)/.test(t)) themes.push("loneliness");

  // Safety / harassment / bullying
  if (/(harass|bully|ragging|threaten|abuse|violence|unsafe|intimidat|coercion|danger|blackmail|extort)/.test(t)) themes.push("safety");

  // Fear / phobia
  if (/(fear|fearful|scared|afraid|phobia|terrified|dread|coward)/.test(t)) themes.push("fear");


  // Sleep and restoration
  if (/(sleep|insomnia|can't sleep|cannot sleep|nightmare|waking up|restless night|oversleep|sleep cycle)/.test(t)) themes.push("sleep");

  // Appetite and nourishment
  if (/(appetite|not eating|overeating|binge eating|food|meal|hungry|nausea|weight loss|weight gain|nutrition)/.test(t)) themes.push("appetite");

  // Body symptoms and somatic stress
  if (/(body|chest tight|headache|stomach|palpitation|breathless|pain|tension|shaking|dizzy|fatigue|somatic)/.test(t)) themes.push("body-symptoms");

  // Legal rights and formal redressal
  if (/(legal|law|rights|police|fir|complaint|court|notice|advocate|lawyer|case|consumer forum|ombudsman)/.test(t)) themes.push("legal-rights");

  // Digital safety
  if (/(phone hacked|account hacked|otp|password|cyber|online abuse|social media|leaked|morphed|privacy|stalking online|digital)/.test(t)) themes.push("digital-safety");

  // Reputation and social standing
  if (/(reputation|defame|defamation|rumour|rumor|people will think|social image|insulted publicly|public shame)/.test(t)) themes.push("social-reputation");

  // Career growth
  if (/(promotion|career growth|appraisal|interview|resume|cv|switch job|new job|professional growth|career move)/.test(t)) themes.push("career-growth");

  // Workplace conflict
  if (/(boss|manager|colleague|coworker|office politics|hr|workplace conflict|toxic workplace|senior|team issue)/.test(t)) themes.push("workplace-conflict");

  // Education administration
  if (/(admission|fees|scholarship|university office|college office|certificate|marksheet|attendance|education complaint)/.test(t)) themes.push("education-admin");

  // Exam performance
  if (/(exam performance|test anxiety|marks|rank|entrance|result|fail|failing|revision|memory|concentration)/.test(t)) themes.push("exam-performance");

  // Time management
  if (/(time management|deadline|late|schedule|routine|no time|too many tasks|calendar|planning)/.test(t)) themes.push("time-management");

  // Procrastination
  if (/(procrastinat|delay|putting off|can't start|cannot start|avoid doing|stuck starting|doomscroll)/.test(t)) themes.push("procrastination");

  // Motivation and drive
  if (/(motivation|demotivated|no drive|no interest|can't continue|give up|discipline|consistency)/.test(t)) themes.push("motivation");

  // Confidence
  if (/(confidence|self doubt|self-doubt|inferior|not capable|imposter|can't speak|low confidence)/.test(t)) themes.push("confidence");

  // Boundaries
  if (/(boundary|boundaries|can't say no|cannot say no|people pleasing|overgiving|space|personal limit)/.test(t)) themes.push("boundaries");

  // Communication
  if (/(communicat|conversation|message|call|talk to|explain|misunderstood|argument|discussion)/.test(t)) themes.push("communication");

  // Trust
  if (/(trust|betray|betrayed|doubt them|suspicious|loyalty|cheating|lied|lie|broken trust)/.test(t)) themes.push("trust");

  // Intimacy
  if (/(intimacy|sexual|physical closeness|affection|touch|desire|bedroom|romantic distance)/.test(t)) themes.push("intimacy");

  // Caregiving load
  if (/(caregiver|caregiving|looking after|taking care|dependent|care load|caretaker)/.test(t)) themes.push("caregiving");

  // Elder care
  if (/(elder|elderly|aged parent|old parent|senior citizen|dementia|grandparent)/.test(t)) themes.push("elder-care");

  // Pregnancy and postpartum
  if (/(pregnant|pregnancy|postpartum|new mother|miscarriage|fertility|ivf|delivery|birth recovery)/.test(t)) themes.push("pregnancy-postpartum");

  // Identity and values
  if (/(values|morals|who i am|identity crisis|authentic|my principles|self respect|self-respect)/.test(t)) themes.push("identity-values");

  // Spirituality and faith
  if (/(spiritual|faith|god|prayer|karma|religion|mandir|temple|gurdwara|church|mosque|divine)/.test(t)) themes.push("spirituality-faith");

  // Cultural belonging
  if (/(culture|caste|community pressure|tradition|belonging|outsider|language|family honour|honor)/.test(t)) themes.push("cultural-belonging");

  // Decision making
  if (/(decision|choose|choice|options|conflicted|which one|should i|whether to|pros and cons)/.test(t)) themes.push("decision-making");

  // Habit and routine
  if (/(habit|routine|daily pattern|streak|morning routine|night routine|lifestyle|discipline)/.test(t)) themes.push("habit-routine");

  // Environment and living conditions
  if (/(environment|room|neighbour|neighbor|noise|pollution|living condition|hostel|pg|house condition)/.test(t)) themes.push("environment");

  // Documentation and evidence
  if (/(document|evidence|proof|screenshot|receipt|recording|paperwork|file|application number|acknowledgement)/.test(t)) themes.push("documentation-evidence");

  // Identity / direction / purpose
  if (/(confus|lost|don't know|not sure|unclear|direction|purpose|meaningless|identity|who am i|lost myself|existential|what should i do|what's the point)/.test(t)) themes.push("direction");

  return themes;
}

type SupportDimensionGuide = {
  id: SupportDimensionId;
  label: string;
  issueId: IssueId;
  route: GuidedSupportRoute;
  // Why this dimension matters, before jumping to action -- grounds the
  // person in what is actually happening instead of only what to do.
  context: string;
  firstAction: string;
  // The concrete sequence from first action to an actually-resolved issue --
  // this is what turns a one-line nudge into a real redress path.
  resolutionSteps: string[];
  // What resolution/conclusion looks like for this specific dimension, so
  // the person has a real, checkable marker instead of guessing when to stop.
  conclusionMarker: string;
  escalation: string;
  // Concrete nearby-search targets, mirroring the 17 broad issues' supportPath
  // -- specific enough to act on, not a generic "find help" prompt.
  supportSearch: Array<{ label: string; query: string }>;
};

