function buildCounsellingPracticeOrchestration(
  themes: SupportDimensionId[],
  languageId: LanguageId
) {
  const dimensionId = themes[0] ?? "direction";
  const guide = supportDimensionGuides[dimensionId] ?? supportDimensionGuides.direction;
  const profile = getSupportPracticeProfile(guide.id);
  const copy = getLocalizedSupportPracticeCopy(profile, languageId);
  const method = meditationMethods.find((item) => item.id === profile.meditationMethodId);
  const chakra = meditationChakraTeachings.find((item) => item.id === profile.chakraId);
  const dimensionLabel = localizedSupportDimensionLabel(guide, languageId);
  const practiceLabel = pickLocalizedText(languageId, {
    english: method?.label ?? "grounded reflective practice",
    hindi: "स्थिर और स्रोत-आधारित चिंतन अभ्यास",
    telugu: "స్థిరమైన, మూలాధారంతో కూడిన ప్రతిబింబ సాధన",
    tamil: "நிலையான, ஆதாரமுள்ள சிந்தனைப் பயிற்சி",
    urdu: "پُرسکون اور ماخذ پر مبنی غور کی مشق"
  });
  const chakraLabel = chakra
    ? languageId === "english"
      ? `${chakra.sanskrit} (${chakra.label})`
      : chakra.sanskrit
    : profile.chakraId;
  const summary = pickLocalizedText(languageId, {
    english: `Coordinated 48-dimension plan — primary focus: ${dimensionLabel}. Calm cue: ${copy.calmCue} Optional reflective practice: ${practiceLabel}, using ${chakraLabel} only as a non-diagnostic attention cue. Path / Help handoff: ${copy.pathHandoff} ${copy.vedicRole}`,
    hindi: `समन्वित 48-आयाम योजना — मुख्य केंद्र: ${dimensionLabel}। Calm संकेत: ${copy.calmCue} वैकल्पिक चिंतन अभ्यास: ${practiceLabel}; ${chakraLabel} का उपयोग केवल गैर-नैदानिक ध्यान-संकेत के रूप में करें। Path / Help हस्तांतरण: ${copy.pathHandoff} ${copy.vedicRole}`,
    telugu: `సమన్వయిత 48-మానదండాల ప్రణాళిక — ప్రధాన దృష్టి: ${dimensionLabel}. Calm సంకేతం: ${copy.calmCue} ఐచ్ఛిక ప్రతిబింబ సాధన: ${practiceLabel}; ${chakraLabel} ను నిర్ధారణ కాని దృష్టి సంకేతంగా మాత్రమే ఉపయోగించండి. Path / Help హ్యాండ్ఆఫ్: ${copy.pathHandoff} ${copy.vedicRole}`,
    tamil: `ஒருங்கிணைந்த 48-பரிமாணத் திட்டம் — முதன்மைக் கவனம்: ${dimensionLabel}. Calm குறிப்பு: ${copy.calmCue} விருப்பமான சிந்தனைப் பயிற்சி: ${practiceLabel}; ${chakraLabel} என்பதை நோயறிதல் அல்லாத கவனக் குறியாக மட்டும் பயன்படுத்தவும். Path / Help மாற்றம்: ${copy.pathHandoff} ${copy.vedicRole}`,
    urdu: `مربوط 48 جہتی منصوبہ — بنیادی توجہ: ${dimensionLabel}۔ Calm اشارہ: ${copy.calmCue} اختیاری غور کی مشق: ${practiceLabel}؛ ${chakraLabel} کو صرف غیر تشخیصی توجہ کے اشارے کے طور پر استعمال کریں۔ Path / Help منتقلی: ${copy.pathHandoff} ${copy.vedicRole}`
  });

  return {
    dimensionId,
    guide,
    profile,
    copy,
    method,
    chakra,
    dimensionLabel,
    practiceLabel,
    chakraLabel,
    summary
  };
}

function localizedSupportDimensionLabel(guide: SupportDimensionGuide, languageId: LanguageId) {
  return pickLocalizedText(languageId, supportDimensionLabelCopy[guide.id] ?? { english: guide.label });
}

function getSupportDimensionPlan(text: string, fallbackIssueId: IssueId): SupportDimensionGuide[] {
  const detected = detectThemes(text);
  const guides = detected.map((theme) => supportDimensionGuides[theme]).filter(Boolean);
  if (guides.length > 0) return guides;
  const fallback = Object.values(supportDimensionGuides).find((guide) => guide.issueId === fallbackIssueId);
  return [fallback ?? supportDimensionGuides.direction];
}

function formatSupportDimensionLabels(guides: SupportDimensionGuide[], languageId: LanguageId) {
  return guides
    .slice(0, 4)
    .map((guide) => localizedSupportDimensionLabel(guide, languageId))
    .join(", ");
}

// ── Real multidimensional reference panel, reused across every section ──────────────
// Several sections previously used a numeric title over a hardcoded
// 5-field (practical/emotional/psychological/reflective/cultural) lookup
// table -- 5 items pretending to be 48. This renders the ACTUAL complete
// supportDimensionGuides dataset instead, the same real data that already
// powers Path's counselling engine. Entries the user has actually surfaced
// this session (activeJourney.detectedThemes, a real classifier output) or
// that belong to their active issue sort to the top; the rest remain
// browsable underneath as a genuine, complete 48-item library.
function orderSupportDimensionsByRelevance(
  issueId: IssueId,
  detectedThemes: SupportDimensionId[]
): SupportDimensionGuide[] {
  const detectedSet = new Set(detectedThemes);
  const relevanceScore = (guide: SupportDimensionGuide) =>
    (detectedSet.has(guide.id) ? 2 : 0) + (guide.issueId === issueId ? 1 : 0);
  return Object.values(supportDimensionGuides).sort(
    (a, b) => relevanceScore(b) - relevanceScore(a)
  );
}

function SupportDimensionLibraryPanel({
  eyebrow,
  actionLabel,
  languageId = "english",
  accentColor = "#066C84",
  moonChartInsightReadings,
  onOpenTab,
  onEmergencyCall,
  openWebsite,
  buildNearbySearchUrl
}: {
  eyebrow: string;
  actionLabel: string;
  languageId?: LanguageId;
  accentColor?: string;
  // Only passed by Path today -- when present, tapping open a dimension also
  // shows its personal Moon Chart complement and a direct route button, so
  // the full multidimensional library becomes actionable, not just readable.
  moonChartInsightReadings?: MoonChart48Reading[];
  onOpenTab?: (tab: TabId) => void;
  onEmergencyCall?: () => Promise<void>;
  openWebsite?: (url: string, title: string) => void | Promise<void>;
  buildNearbySearchUrl?: (query: string) => string;
}) {
  const { issueGuide, detectedThemes } = useCrossSectionSignal();
  const [expanded, setExpanded] = useState(false);
  const [openDimensionId, setOpenDimensionId] = useState<SupportDimensionId | null>(null);
  const ordered = useMemo(
    () => orderSupportDimensionsByRelevance(issueGuide.id, detectedThemes),
    [issueGuide.id, detectedThemes]
  );
  const isRelevant = (guide: SupportDimensionGuide) =>
    guide.issueId === issueGuide.id || detectedThemes.includes(guide.id);
  const relevantCount = ordered.filter(isRelevant).length;
  const visible = expanded ? ordered : ordered.slice(0, 6);
  const openDimensionMoonChart = useMemo(
    () =>
      openDimensionId
        ? buildDimensionMoonChartComplement(openDimensionId, moonChartInsightReadings ?? [])
        : null,
    [openDimensionId, moonChartInsightReadings]
  );
  const openDimensionPracticeProfile = useMemo(
    () => (openDimensionId ? getSupportPracticeProfile(openDimensionId) : null),
    [openDimensionId]
  );
  const openDimensionPracticeCopy = useMemo(
    () =>
      openDimensionPracticeProfile
        ? getLocalizedSupportPracticeCopy(openDimensionPracticeProfile, languageId)
        : null,
    [openDimensionPracticeProfile, languageId]
  );
  const openDimensionMeditationMethod = useMemo(
    () =>
      openDimensionPracticeProfile
        ? meditationMethods.find(
            (method) => method.id === openDimensionPracticeProfile.meditationMethodId
          ) ?? null
        : null,
    [openDimensionPracticeProfile]
  );
  const openDimensionChakra = useMemo(
    () =>
      openDimensionPracticeProfile
        ? meditationChakraTeachings.find(
            (chakra) => chakra.id === openDimensionPracticeProfile.chakraId
          ) ?? null
        : null,
    [openDimensionPracticeProfile]
  );
  const routeLabel = (route: GuidedSupportRoute) =>
    route === "redress"
      ? pickLocalizedText(languageId, { english: "Formal remedy · Redress", hindi: "औपचारिक समाधान · शिकायत", telugu: "అధికారిక పరిష్కారం · పరిహారం", tamil: "அதிகாரப்பூர்வ நிவாரணம் · உதவி", urdu: "باضابطہ حل · ازالہ" })
      : route === "professional"
        ? pickLocalizedText(languageId, { english: "Professional support", hindi: "पेशेवर सहायता", telugu: "వృత్తిపరమైన మద్దతు", tamil: "தொழில்முறை ஆதரவு", urdu: "پیشہ ورانہ مدد" })
        : route === "urgent"
          ? pickLocalizedText(languageId, { english: "Urgent safety support", hindi: "तत्काल सुरक्षा सहायता", telugu: "తక్షణ భద్రతా మద్దతు", tamil: "உடனடி பாதுகாப்பு ஆதரவு", urdu: "فوری حفاظتی مدد" })
          : pickLocalizedText(languageId, { english: "Guided practical action · Path", hindi: "मार्गदर्शित व्यावहारिक कदम · मार्ग", telugu: "మార్గదర్శిత ప్రాయోగిక చర్య · మార్గం", tamil: "வழிகாட்டப்பட்ட நடைமுறை செயல் · பாதை", urdu: "رہنمائی والی عملی کارروائی · راستہ" });

  return (
    <View style={{ marginHorizontal: 16, marginBottom: 14, backgroundColor: "#E1EEEC", borderRadius: 16, borderWidth: 1, borderColor: accentColor + "33", overflow: "hidden" }}>
      <View style={{ backgroundColor: accentColor + "14", paddingHorizontal: 14, paddingVertical: 10, flexDirection: "row", justifyContent: "space-between", alignItems: "center" }}>
        <Text style={{ color: accentColor, fontSize: 12, fontWeight: "700", textTransform: "uppercase", letterSpacing: 1.2 }}>
          {eyebrow} · {pickLocalizedText(languageId, { english: "multidimensional support", hindi: "बहु-आयामी सहायता", telugu: "బహుళ-మానదండాల మద్దతు", tamil: "பல பரிமாண ஆதரவு", urdu: "کثیر جہتی مدد" })}
        </Text>
        <Text style={{ color: "#4C6674", fontSize: 12 }}>{localizedIssueGuideLabel(issueGuide.id, languageId)}</Text>
      </View>
      <Text style={{ color: "#506673", fontSize: 12, paddingHorizontal: 14, paddingTop: 8, paddingBottom: 4, lineHeight: 16 }}>
        {relevantCount > 0
          ? pickLocalizedText(languageId, {
              english: `${relevantCount} relevant support perspectives match your active focus${detectedThemes.length > 0 ? " and Path conversation" : ""} and are shown first. Tap any perspective for its full escalation guidance and route.`,
              hindi: `${relevantCount} प्रासंगिक सहायता दृष्टिकोण आपके सक्रिय फोकस${detectedThemes.length > 0 ? " और Path बातचीत" : ""} से मेल खाते हैं और पहले दिखते हैं। किसी भी दृष्टिकोण पर टैप करके उसका पूरा मार्गदर्शन और रास्ता देखें।`,
              telugu: `${relevantCount} సంబంధిత మద్దతు దృష్టికోణాలు మీ క్రియాశీల దృష్టి${detectedThemes.length > 0 ? " మరియు Path సంభాషణ" : ""}కి సరిపోతాయి మరియు ముందుగా చూపబడతాయి. ఏ దృష్టికోణాన్నైనా ట్యాప్ చేసి దాని పూర్తి escalation మార్గదర్శకత మరియు route చూడండి.`,
              tamil: `${relevantCount} தொடர்புடைய ஆதரவு பார்வைகள் உங்கள் செயலில் உள்ள கவனம்${detectedThemes.length > 0 ? " மற்றும் Path உரையாடல்" : ""}க்கு பொருந்துகின்றன, முதலில் காட்டப்படுகின்றன. எந்தப் பார்வையையும் தட்டினால் அதன் முழு escalation வழிகாட்டல் மற்றும் பாதை கிடைக்கும்.`,
              urdu: `${relevantCount} متعلقہ مدد کے زاویے آپ کی فعال توجہ${detectedThemes.length > 0 ? " اور Path گفتگو" : ""} سے ملتے ہیں اور پہلے دکھائے جاتے ہیں۔ کسی بھی زاویے پر ٹیپ کریں اور اس کی مکمل escalation رہنمائی اور راستہ دیکھیں۔`
            })
          : pickLocalizedText(languageId, {
              english: "The complete multidimensional support library used by the counselling engine. Tap any perspective for its full escalation guidance and route.",
              hindi: "परामर्श इंजन द्वारा इस्तेमाल की जाने वाली पूरी बहु-आयामी सहायता लाइब्रेरी। किसी भी दृष्टिकोण पर टैप करके उसका पूरा मार्गदर्शन और रास्ता देखें।",
              telugu: "కౌన్సెలింగ్ ఇంజిన్ ఉపయోగించే పూర్తి బహుళ-మానదండాల మద్దతు గ్రంథాలయం. ఏ దృష్టికోణాన్నైనా ట్యాప్ చేసి దాని పూర్తి escalation మార్గదర్శకత మరియు route చూడండి.",
              tamil: "ஆலோசனை இயந்திரம் பயன்படுத்தும் முழு பல பரிமாண ஆதரவு நூலகம். எந்தப் பார்வையையும் தட்டினால் அதன் முழு escalation வழிகாட்டல் மற்றும் பாதை கிடைக்கும்.",
              urdu: "کاؤنسلنگ انجن کی مکمل کثیر جہتی مدد لائبریری۔ کسی بھی زاویے پر ٹیپ کریں اور اس کی مکمل escalation رہنمائی اور راستہ دیکھیں۔"
            })}
      </Text>
      {visible.map((guide, i) => {
        const relevant = isRelevant(guide);
        const isOpen = openDimensionId === guide.id;
        return (
          <View key={guide.id}>
            <Pressable
              accessibilityRole="button"
              accessibilityState={{ expanded: isOpen }}
              accessibilityLabel={`${localizedSupportDimensionLabel(guide, languageId)}, ${pickLocalizedText(languageId, { english: "tap for escalation guidance and route", hindi: "विस्तृत मार्गदर्शन और रास्ते के लिए टैप करें", telugu: "escalation మార్గదర్శకత మరియు route కోసం ట్యాప్ చేయండి", tamil: "escalation வழிகாட்டல் மற்றும் பாதைக்குத் தட்டவும்", urdu: "escalation رہنمائی اور راستے کے لیے ٹیپ کریں" })}`}
              onPress={() => setOpenDimensionId(isOpen ? null : guide.id)}
              style={({ pressed }) => [{
                flexDirection: "row", alignItems: "flex-start", paddingHorizontal: 14, paddingVertical: 8,
                borderTopWidth: i === 0 ? 0 : 1, borderTopColor: "rgba(36,56,74,0.10)",
                backgroundColor: pressed ? accentColor + "10" : relevant ? accentColor + "0C" : "transparent"
              }]}
            >
              <View style={{ width: 3, borderRadius: 2, alignSelf: "stretch", marginRight: 10, marginTop: 1, backgroundColor: relevant ? accentColor : "rgba(100,116,139,0.25)" }} />
              <View style={{ flex: 1 }}>
                <Text style={{ color: relevant ? accentColor : "#4C6674", fontSize: 12, fontWeight: "800", textTransform: "capitalize", marginBottom: 2 }}>
                  {localizedSupportDimensionLabel(guide, languageId)}
                </Text>
                <Text style={{ color: "#446573", fontSize: 12, lineHeight: 17 }}>{actionLabel}: {guide.firstAction}</Text>
              </View>
                <Text style={{ color: accentColor, fontSize: 12, fontWeight: "700", marginLeft: 6 }}>{isOpen ? "▾" : "▸"}</Text>
              </Pressable>
            {isOpen ? (
              <View style={{ paddingHorizontal: 14, paddingBottom: 12, paddingTop: 2, backgroundColor: accentColor + "08" }}>
                <View style={{ backgroundColor: accentColor + "18", alignSelf: "flex-start", borderRadius: 999, paddingHorizontal: 10, paddingVertical: 3, marginBottom: 8, borderWidth: 1, borderColor: accentColor + "40" }}>
                  <Text style={{ color: accentColor, fontSize: 12, fontWeight: "800" }}>{routeLabel(guide.route)}</Text>
                </View>
                <Text style={{ color: "#263244", fontSize: 12, lineHeight: 17, marginBottom: 8 }}>{guide.context}</Text>
                <Text style={{ color: accentColor, fontSize: 12, fontWeight: "700", textTransform: "uppercase", letterSpacing: 0.6, marginBottom: 4 }}>
                  {pickLocalizedText(languageId, { english: "Path to resolution", hindi: "समाधान का रास्ता", telugu: "పరిష్కారానికి మార్గం", tamil: "தீர்வுக்கான பாதை", urdu: "حل تک راستہ" })}
                </Text>
                {guide.resolutionSteps.map((step, stepIndex) => (
                  <View key={`${guide.id}-step-${stepIndex}`} style={{ flexDirection: "row", alignItems: "flex-start", marginBottom: 4, gap: 6 }}>
                    <Text style={{ color: accentColor, fontSize: 12, fontWeight: "700" }}>{stepIndex + 1}.</Text>
                    <Text style={{ color: "#263244", fontSize: 12, lineHeight: 17, flex: 1 }}>{step}</Text>
                  </View>
                ))}
                <Text style={{ color: "#263244", fontSize: 12, lineHeight: 17, marginTop: 6, marginBottom: 6 }}>
                  <Text style={{ fontWeight: "900" }}>{pickLocalizedText(languageId, { english: "Resolved when: ", hindi: "सुलझा माना जाए जब: ", telugu: "పరిష్కారమైనప్పుడు: ", tamil: "தீர்வு எனக் கருதப்படும் போது: ", urdu: "حل ہو جائے جب: " })}</Text>{guide.conclusionMarker}
                </Text>
                <Text style={{ color: "#263244", fontSize: 12, lineHeight: 17, marginBottom: 6 }}>
                  <Text style={{ fontWeight: "900" }}>{pickLocalizedText(languageId, { english: "Escalate when: ", hindi: "और ऊपर बढ़ाएँ जब: ", telugu: "ఎప్పుడు పైకి పంపాలి: ", tamil: "மேலேற்ற வேண்டிய போது: ", urdu: "اس وقت اوپر بڑھائیں جب: " })}</Text>{guide.escalation}
                </Text>
                {openDimensionMoonChart ? (
                  <Text style={{ color: "#263244", fontSize: 12, lineHeight: 17, marginBottom: 8 }}>
                    <Text style={{ fontWeight: "900" }}>{pickLocalizedText(languageId, { english: "Moon Chart: ", hindi: "चंद्र-चार्ट: ", telugu: "చంద్ర చార్ట్: ", tamil: "சந்திர அட்டவணை: ", urdu: "چاندی چارٹ: " })}</Text>
                    {openDimensionMoonChart.average}/100 ({openDimensionMoonChart.verdict.toLowerCase()}) · {openDimensionMoonChart.remedyTitle}: {openDimensionMoonChart.remedy}
                  </Text>
                ) : null}
                {openDimensionPracticeProfile && openDimensionPracticeCopy ? (
                  <View
                    style={{
                      backgroundColor:
                        openDimensionPracticeProfile.priority === "escalate"
                          ? "#FFF1F0"
                          : "#F7FBFA",
                      borderWidth: 1,
                      borderColor:
                        openDimensionPracticeProfile.priority === "escalate"
                          ? "#B91C1C55"
                          : accentColor + "35",
                      borderRadius: 12,
                      padding: 10,
                      marginBottom: 10,
                      gap: 5
                    }}
                  >
                    <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center", gap: 8 }}>
                      <Text style={{ color: accentColor, fontSize: 12, fontWeight: "700", textTransform: "uppercase", letterSpacing: 0.6, flex: 1 }}>
                        {pickLocalizedText(languageId, {
                          english: "Synchronized support plan",
                          hindi: "समन्वित सहायता योजना",
                          telugu: "సమన్వయ మద్దతు ప్రణాళిక",
                          tamil: "ஒருங்கிணைந்த ஆதரவு திட்டம்",
                          urdu: "مربوط مدد کا منصوبہ"
                        })}
                      </Text>
                      <Text style={{ color: openDimensionPracticeProfile.priority === "escalate" ? "#B91C1C" : accentColor, fontSize: 12, fontWeight: "700", textTransform: "uppercase" }}>
                        {openDimensionPracticeProfile.priority}
                      </Text>
                    </View>
                    <Text style={{ color: "#263244", fontSize: 12, lineHeight: 17 }}>
                      <Text style={{ fontWeight: "900" }}>
                        {pickLocalizedText(languageId, { english: "Calm · ", hindi: "शांति-सहायता · ", telugu: "శాంతి సహాయం · ", tamil: "அமைதி உதவி · ", urdu: "سکون کی مدد · " })}
                      </Text>{openDimensionPracticeCopy.calmCue}
                    </Text>
                    <Text style={{ color: "#263244", fontSize: 12, lineHeight: 17 }}>
                      <Text style={{ fontWeight: "900" }}>
                        {pickLocalizedText(languageId, { english: "Meditation · ", hindi: "ध्यान · ", telugu: "ధ్యానం · ", tamil: "தியானம் · ", urdu: "مراقبہ · " })}
                      </Text>
                      {openDimensionMeditationMethod?.label ?? openDimensionPracticeProfile.meditationMethodId}
                      {openDimensionChakra ? ` · ${openDimensionChakra.label}` : ""}
                    </Text>
                    <Text style={{ color: "#263244", fontSize: 12, lineHeight: 17 }}>
                      <Text style={{ fontWeight: "900" }}>
                        {pickLocalizedText(languageId, { english: "Path / Help / Redress · ", hindi: "मार्ग / सहायता / निवारण · ", telugu: "మార్గం / సహాయం / పరిహారం · ", tamil: "வழி / உதவி / நிவாரணம் · ", urdu: "راستہ / مدد / ازالہ · " })}
                      </Text>{openDimensionPracticeCopy.pathHandoff}
                    </Text>
                    <Text style={{ color: "#5A6674", fontSize: 12, lineHeight: 16 }}>
                      <Text style={{ fontWeight: "900" }}>
                        {pickLocalizedText(languageId, { english: "Vedic layer · ", hindi: "वैदिक परत · ", telugu: "వేద పొర · ", tamil: "வேத அடுக்கு · ", urdu: "ویدک تہہ · " })}
                      </Text>{openDimensionPracticeCopy.vedicRole}
                    </Text>
                  </View>
                ) : null}
                <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 8 }}>
                  {onOpenTab && guide.route === "redress" ? (
                    <Pressable accessibilityRole="button" onPress={() => onOpenTab("redress")} style={{ backgroundColor: accentColor, borderRadius: 8, paddingHorizontal: 10, paddingVertical: 6 }}>
                      <Text style={{ color: "#FFFFFF", fontSize: 12, fontWeight: "800" }}>
                        {pickLocalizedText(languageId, { english: "Open Redress", hindi: "शिकायत खोलें", telugu: "పరిహారం తెరవండి", tamil: "நிவாரணத்தைத் திறக்கவும்", urdu: "ازالہ کھولیں" })}
                      </Text>
                    </Pressable>
                  ) : null}
                  {onOpenTab && guide.route === "guide" ? (
                    <Pressable accessibilityRole="button" onPress={() => onOpenTab("guide")} style={{ backgroundColor: accentColor, borderRadius: 8, paddingHorizontal: 10, paddingVertical: 6 }}>
                      <Text style={{ color: "#FFFFFF", fontSize: 12, fontWeight: "800" }}>
                        {pickLocalizedText(languageId, { english: "Open Path", hindi: "मार्ग खोलें", telugu: "మార్గం తెరవండి", tamil: "பாதையைத் திறக்கவும்", urdu: "راستہ کھولیں" })}
                      </Text>
                    </Pressable>
                  ) : null}
                  {openWebsite && buildNearbySearchUrl
                    ? guide.supportSearch.map((target) => (
                        <Pressable
                          key={`${guide.id}-search-${target.label}`}
                          accessibilityRole="button"
                          onPress={() => void openWebsite(buildNearbySearchUrl(target.query), target.label)}
                          style={{ backgroundColor: accentColor, borderRadius: 8, paddingHorizontal: 10, paddingVertical: 6 }}
                        >
                          <Text style={{ color: "#FFFFFF", fontSize: 12, fontWeight: "800" }}>
                            {pickLocalizedText(languageId, { english: "Find: ", hindi: "खोजें: ", telugu: "కనుగొనండి: ", tamil: "தேடு: ", urdu: "تلاش کریں: " })}{target.label}
                          </Text>
                        </Pressable>
                      ))
                    : null}
                  {onEmergencyCall ? (
                    <Pressable accessibilityRole="button" onPress={onEmergencyCall} style={{ backgroundColor: "#B91C1C", borderRadius: 8, paddingHorizontal: 10, paddingVertical: 6 }}>
                      <Text style={{ color: "#FFFFFF", fontSize: 12, fontWeight: "800" }}>SOS</Text>
                    </Pressable>
                  ) : null}
                </View>
              </View>
            ) : null}
          </View>
        );
      })}
      <Pressable
        onPress={() => { animateDisclosure(); setExpanded((value) => !value); }}
        accessibilityRole="button"
        accessibilityLabel={expanded
          ? pickLocalizedText(languageId, { english: "Show fewer perspectives", hindi: "कम दृष्टिकोण दिखाएँ", telugu: "తక్కువ దృష్టికోణాలు చూపించు", tamil: "குறைவான பார்வைகள் காட்டவும்", urdu: "کم زاویے دکھائیں" })
          : pickLocalizedText(languageId, { english: "Show all support perspectives", hindi: "सभी सहायता दृष्टिकोण दिखाएँ", telugu: "అన్ని మద్దతు దృష్టికోణాలను చూపించు", tamil: "அனைத்து ஆதரவு பார்வைகளையும் காட்டவும்", urdu: "تمام مدد کے زاویے دکھائیں" })}
        style={{ paddingVertical: 10, alignItems: "center", borderTopWidth: 1, borderTopColor: "rgba(255,255,255,0.06)" }}
      >
        <Text style={{ color: accentColor, fontSize: 12, fontWeight: "800" }}>
          {expanded
            ? pickLocalizedText(languageId, { english: "Show fewer ↑", hindi: "कम दिखाएँ ↑", telugu: "తక్కువ చూపించు ↑", tamil: "குறைவாகக் காட்டவும் ↑", urdu: "کم دکھائیں ↑" })
            : pickLocalizedText(languageId, { english: `Show all perspectives ↓ (${ordered.length - visible.length} more)`, hindi: `सभी दृष्टिकोण दिखाएँ ↓ (${ordered.length - visible.length} और)`, telugu: `అన్ని దృష్టికోణాలు చూపించు ↓ (${ordered.length - visible.length} మరిన్ని)`, tamil: `அனைத்து பார்வைகளையும் காட்டவும் ↓ (${ordered.length - visible.length} மேலும்)`, urdu: `تمام زاویے دکھائیں ↓ (${ordered.length - visible.length} مزید)` })}
        </Text>
      </Pressable>
    </View>
  );
}

function buildSupportDimensionQuestionBank(theme: SupportDimensionId, languageId: LanguageId = "english"): string[] {
  const guide = supportDimensionGuides[theme] ?? supportDimensionGuides.direction;
  const label = localizedSupportDimensionLabel(guide, languageId);
  const routeLabel =
    guide.route === "urgent" ? "urgent safety support" :
    guide.route === "professional" ? "professional support" :
    guide.route === "redress" ? "formal remedy or redressal" :
    guide.route === "guide" ? "guided practical action" :
    "steady support";

  // These 7 questions used to be a single label-substituted template shared
  // identically (word for word, except the topic name) across all ~33
  // dimensions that don't have a bespoke hand-written question bank in
  // buildCounselingQuestions above -- which reads exactly like a generic
  // chatbot mad-lib, the opposite of what a real counselling engine should
  // feel like. supportDimensionGuides already has rich, specifically-authored
  // context/firstAction/resolutionSteps/escalation text per dimension (see
  // that type's own comments) that simply wasn't being used here. Weaving
  // guide.context and guide.escalation into the questions grounds each one in
  // real, already-written material instead of a mechanically repeated shape.
  return [
    `${guide.context} With that in mind -- what happened most recently that made ${label} feel important today? I want the real situation, not a generic category.`,
    `How long has ${label} been affecting you, and is it getting heavier, lighter, or changing shape?`,
    `Where does ${label} show up most strongly -- body, thoughts, emotions, relationships, work or home?`,
    `Who else is involved in ${label}, and what do you need from them that you are not getting right now?`,
    `What have you already tried for ${label}, and what made those attempts work, fail, or feel incomplete?`,
    `If we choose the safest ${routeLabel} route, what would one acceptable next step look like for you? For reference, ${guide.firstAction.charAt(0).toLowerCase()}${guide.firstAction.slice(1)}`,
    `One thing before we act: ${guide.escalation.charAt(0).toLowerCase()}${guide.escalation.slice(1)} Does anything like that apply right now, or is this steady enough to keep working through together?`,
  ];
}

