function getCounselingMoonChartCategories(themes: SupportDimensionId[]): MoonChart48Category[] {
  const categories = new Set<MoonChart48Category>();
  themes.forEach((theme) => {
    (COUNSELING_THEME_TO_MOON48_CATEGORIES[theme] ?? ["mind", "growth"]).forEach((category) => categories.add(category));
  });
  if (categories.size === 0) {
    categories.add("mind");
    categories.add("growth");
  }
  return Array.from(categories);
}

function buildMoonChartCounselingOverlay(
  themes: SupportDimensionId[],
  moonChartInsightReadings: MoonChart48Reading[] = []
): string {
  if (moonChartInsightReadings.length === 0) {
    return "";
  }

  const categories = getCounselingMoonChartCategories(themes);
  const relevant = moonChartInsightReadings.filter((reading) => categories.includes(reading.category));
  const pool = relevant.length > 0 ? relevant : moonChartInsightReadings;
  const strongest = [...pool].sort((a, b) => b.score - a.score).slice(0, 3);
  const careful = [...pool].sort((a, b) => a.score - b.score).slice(0, 3);
  const average = Math.round(pool.reduce((sum, item) => sum + item.score, 0) / pool.length);
  const topLine = strongest.map((item) => `${item.label} ${item.score}/100`).join("; ");
  const carefulLine = careful.map((item) => `${item.label} ${item.score}/100`).join("; ");
  const primaryRemedy = careful[0]?.remedy ?? strongest[0]?.remedy ?? "Moon-chart remedy: keep the next step small, calm, and repeatable today.";

  return [
    `Multi-dimensional Vedic counselling layer: I also checked the lunar pattern connected to this issue. The relevant support average is ${average}/100.`,
    `Supported capacities: ${topLine}.`,
    `Care points: ${carefulLine}.`,
    `How to use this today: treat the supported areas as resources, and protect the careful areas before making a big decision. ${primaryRemedy}`,
    "This is a reflective Vedic timing layer, not a medical, legal, or emergency substitute."
  ].join("\n");
}

function shouldAddMoonChartJourneyStep(themes: SupportDimensionId[], moonChartInsightReadings: MoonChart48Reading[] = []): boolean {
  if (moonChartInsightReadings.length === 0) return false;
  const categories = getCounselingMoonChartCategories(themes);
  return moonChartInsightReadings.some((reading) => categories.includes(reading.category));
}

// Maps each Path/Guide issue onto the multidimensional Moon Chart categories most
// relevant to it, mirroring COUNSELING_THEME_TO_MOON48_CATEGORIES above so the
// Path tab draws on the exact same multidimensional Moon Chart engine the
// Automatic Counselling chat already uses — instead of Path staying a
// text-only lens system with no personal-chart complement.
const ISSUE_TO_MOON48_CATEGORIES: Record<IssueId, MoonChart48Category[]> = {
  general: ["mind", "growth"],
  anger: ["mind", "risk", "relationship"],
  anxiety: ["mind", "body", "risk"],
  fear: ["risk", "mind", "body"],
  overconfidence: ["risk", "self", "mind"],
  stigma: ["self", "relationship", "spiritual"],
  burnout: ["body", "mind", "work"],
  loneliness: ["relationship", "mind", "spiritual"],
  grief: ["mind", "family", "spiritual", "relationship"],
  identity: ["self", "spiritual", "growth"],
  health: ["body", "mind", "risk"],
  financial: ["money", "mind", "risk"],
  relationship: ["relationship", "mind", "family"],
  parenting: ["family", "mind", "relationship"],
  trauma: ["risk", "mind", "body", "spiritual"],
  academic: ["growth", "mind", "work"],
  addiction: ["body", "mind", "risk", "growth"]
};

type PathMoonChartComplement = {
  average: number;
  verdict: MoonChart48Verdict;
  categories: MoonChart48Category[];
  strongest: MoonChart48Reading[];
  careful: MoonChart48Reading[];
  remedyTitle: string;
  remedy: string;
};

// Builds the same kind of "supported vs careful" Moon Chart read the
// counselling overlay produces, but returns structured data (not a prose
// string) so it can render as a proper visual card instead of a paragraph
// of injected chat text. Shared by both the 17 broad Path issues and, below,
// each of the 48 fine-grained support dimensions -- one calculation, reused
// wherever a category set needs a personal-chart complement.
function buildMoonChartComplementForCategories(
  categories: MoonChart48Category[],
  moonChartInsightReadings: MoonChart48Reading[]
): PathMoonChartComplement | null {
  if (moonChartInsightReadings.length === 0) return null;
  const relevant = moonChartInsightReadings.filter((reading) => categories.includes(reading.category));
  const pool = relevant.length > 0 ? relevant : moonChartInsightReadings;
  const strongest = [...pool].sort((a, b) => b.score - a.score).slice(0, 3);
  const careful = [...pool].sort((a, b) => a.score - b.score).slice(0, 3);
  const average = Math.round(pool.reduce((sum, item) => sum + item.score, 0) / pool.length);
  const anchor = careful[0] ?? strongest[0];
  return {
    average,
    verdict: moonChartVerdict(average),
    categories,
    strongest,
    careful,
    remedyTitle: anchor?.remedyTitle ?? "Today's care point",
    remedy: anchor?.remedy ?? "Keep the next step small, calm, and repeatable today."
  };
}

function buildPathMoonChartComplement(
  issueId: IssueId,
  moonChartInsightReadings: MoonChart48Reading[]
): PathMoonChartComplement | null {
  const categories = ISSUE_TO_MOON48_CATEGORIES[issueId] ?? ["mind", "growth"];
  return buildMoonChartComplementForCategories(categories, moonChartInsightReadings);
}

// Same complement, scoped to one of the 48 fine-grained support dimensions
// instead of one of the 17 broad Path issues -- reuses the exact category
// mapping (getCounselingMoonChartCategories) the Automatic Counselling
// engine already relies on, so a dimension's Moon Chart read here and its
// Moon Chart read inside a counselling reply are always the same numbers.
function buildDimensionMoonChartComplement(
  dimensionId: SupportDimensionId,
  moonChartInsightReadings: MoonChart48Reading[]
): PathMoonChartComplement | null {
  const categories = getCounselingMoonChartCategories([dimensionId]);
  return buildMoonChartComplementForCategories(categories, moonChartInsightReadings);
}

function buildCounselingReflectionCue(theme: SupportDimensionId, turnIndex: number): string {
  const commonCues = [
    "separate the event from the story your mind is adding to it.",
    "notice that a feeling can be present without becoming your whole identity.",
    "name the part that is yours to act on and the part that is outside your control today.",
    "choose the value that should lead the next step: truth, safety, care, dignity, fairness, or rest.",
    "look for what can be released now: comparison, blame, rehearsal, or the need to solve everything at once.",
    "bring the answer back to one honest step, one boundary, or one request."
  ];
  const byTheme: Partial<Record<SupportDimensionId, string>> = {
    trauma: "stay within what feels safe; a broad outline is enough, and protection comes before analysis.",
    grief: "let the loss be named without forcing it to make sense today.",
    addiction: "look for the urge, the trigger, and the unmet need underneath the pattern.",
    anxiety: "separate actual danger from imagined danger before deciding.",
    anger: "look under the heat for the hurt, boundary, fear, or unfairness asking for attention.",
    fear: "check whether courage here means a big leap or one small protected step.",
    "self-image": "notice whether the inner critic is giving useful information or only punishment.",
    "social-reputation": "separate the issue from your identity; a problem is not the whole person.",
    relationship: "hold care and self-respect together; neither one has to erase the other.",
    loneliness: "notice whether the need is company, being understood, or feeling useful somewhere.",
    burnout: "treat exhaustion as information about load and recovery, not as a defect in character.",
    financial: "separate the numbers from the shame so the practical problem can be solved.",
    academic: "separate performance from worth; then name the next study action clearly.",
    "identity-values": "look past roles and labels toward what remains true when pressure quiets.",
    direction: "choose the smallest reversible step rather than forcing a life-sized answer.",
    health: "separate medical facts, uncertainty, and fear; each needs a different response."
  };
  return `As you answer, ${byTheme[theme] ?? commonCues[Math.min(turnIndex, commonCues.length - 1)]}`;
}

function buildCounselingCoreProbe(allUserText: string, turnIndex: number): string | null {
  const text = allUserText.trim().toLowerCase();
  if (!text) return null;

  // A premium guided conversation should not walk through a fixed interview
  // regardless of what the person has already explained. These signals detect
  // which core layer is still missing, then select one warm, focused question.
  // Rotating the starting point by turn prevents the guide from repeating the
  // same unanswered prompt while still working toward a complete picture.
  const probes: Array<{ seen: RegExp; question: string }> = [
    {
      seen: /\b(because|after|when|since|started|happened|trigger|due to|led to)\b/,
      question: "What was happening around the time this began or became harder? One specific moment or pattern is enough."
    },
    {
      seen: /\b(today|yesterday|recent|day|week|month|year|ago|for a while|long time|since)\b/,
      question: "How long has this been affecting you, and has it been steady, improving, or becoming more difficult?"
    },
    {
      seen: /\b(sleep|appetite|eat|body|work|study|focus|relationship|daily|avoid|function|energy|concentrat)\w*\b/,
      question: "Where is this affecting daily life most right now — sleep, concentration, work or study, relationships, or your body?"
    },
    {
      seen: /\b(told|spoke|talked|support|friend|family|counsellor|counselor|doctor|teacher|mentor|colleague|alone)\b/,
      question: "Who, if anyone, understands what you are carrying? Tell me whether you feel supported, partly understood, or mostly alone with it."
    },
    {
      seen: /\b(tried|attempted|helped|worked|practice|spoke to|asked|changed|stopped|started doing)\b/,
      question: "What have you already tried, even briefly, and what made it help, fail, or feel difficult to continue?"
    },
    {
      seen: /\b(want|need|hope|would help|outcome|change|clarity|decision|relief|next step)\b/,
      question: "What would a useful outcome from this conversation look like for you today — relief, clarity, a decision, a boundary, or a practical plan?"
    },
    {
      seen: /\b(core|main issue|hardest part|most painful|underneath|really about)\b/,
      question: "If you had to name the hardest part beneath everything else, what feels most painful, unsafe, unfair, or unresolved?"
    }
  ];
  const start = Math.min(turnIndex, probes.length - 1);
  const ordered = [...probes.slice(start), ...probes.slice(0, start)];
  return ordered.find((probe) => !probe.seen.test(text))?.question ?? null;
}

/**
 * Supreme-level adaptive counseling question builder.
 * Full multidimensional coverage: bespoke banks for core themes plus generated
 * high-quality banks for every advanced dimension in SupportDimensionId.
 * Branches across themes for turns 3-5.
 */

// Between-turn acknowledgment. The counselling engine used to acknowledge
// only on turn one (see buildCounselingAcknowledgment) and then fire raw
// questions every reply after that. A person quickly starts to feel
// interrogated rather than heard, no matter how careful the question is.
//
// This is small on purpose. A real counsellor's between-turn moves are
// almost always: "I hear you" + one specific echo. Two lines, not a
// paragraph. Rotates between openers by turn index so the same phrase does
// not repeat back-to-back, and mirrors one concrete detail from the most
// recent reply when it can find one -- if not, it just holds warmth.
function buildBetweenTurnAcknowledgment(
  latestUserText: string,
  turnIndex: number,
  languageId: LanguageId = "english"
): string {
  if (languageId !== "english") {
    const localizedOpeners: Partial<Record<LanguageId, string[]>> = {
      hindi: ["यह साझा करने के लिए धन्यवाद।", "आपकी बात समझ में आती है।", "मैं आपको सुन रहा हूँ।", "यह बहुत कुछ सँभालने जैसा है।", "मैं आपके साथ इस बात पर बना हुआ हूँ।"],
      telugu: ["ఇది పంచుకున్నందుకు ధన్యవాదాలు.", "మీరు చెప్పింది అర్థమవుతోంది.", "నేను మిమ్మల్ని వింటున్నాను.", "ఇది మోయడానికి చాలా భారంగా ఉంది.", "ఈ విషయంలో నేను మీతోనే ఉన్నాను."],
      tamil: ["இதைப் பகிர்ந்ததற்கு நன்றி.", "நீங்கள் சொல்வது புரிகிறது.", "நான் உங்களைக் கேட்கிறேன்.", "இது தாங்குவதற்கு மிகவும் அதிகம்.", "இந்தப் பேச்சில் நான் உங்களுடன் இருக்கிறேன்."],
      urdu: ["یہ بات بتانے کا شکریہ۔", "آپ کی بات سمجھ میں آتی ہے۔", "میں آپ کو سن رہا ہوں۔", "یہ سنبھالنے کے لیے بہت کچھ ہے۔", "میں اس بات میں آپ کے ساتھ ہوں۔"]
    };
    const translatedOpeners = localizedOpeners[languageId];
    if (translatedOpeners?.length) return translatedOpeners[turnIndex % translatedOpeners.length];
  }
  const openers = [
    "Thank you for saying that.",
    "That makes sense.",
    "I hear you.",
    "That is a lot to hold.",
    "Yes -- I understand.",
    "I am staying with you on this."
  ];
  const opener = openers[turnIndex % openers.length];

  // A concrete echo grounds the acknowledgment in what the person actually
  // said, so the warmth does not read as generic. We look for a short noun
  // phrase after common emotional stems ("i feel ___", "it makes me ___",
  // "the hardest part is ___"). If nothing lands cleanly, the opener alone
  // is honest and enough -- fabricating an echo would be worse than none.
  const t = latestUserText.trim();
  const echoPatterns: Array<RegExp> = [
    /\bi (?:feel|felt) (?:so |really |quite |very |kind of |a bit )?([a-z ,-]{3,40}?)(?:[.!?,]|$| when | because | and )/i,
    /\b(?:it|this|that|the whole thing) (?:makes|made|leaves|left) me (?:feel )?([a-z ,-]{3,40}?)(?:[.!?,]|$| when | because | and )/i,
    /\bthe hardest part (?:is |was )([a-z ,-]{3,60}?)(?:[.!?,]|$)/i,
    /\bwhat i (?:really )?(?:want|need) is ([a-z ,-]{3,60}?)(?:[.!?,]|$)/i
  ];
  let echo: string | null = null;
  for (const re of echoPatterns) {
    const m = t.match(re);
    if (m && m[1]) { echo = m[1].trim().replace(/\s+/g, " "); break; }
  }

  if (echo && echo.length >= 3 && echo.length <= 60) {
    // Reflect it back in the second person so it lands as recognition, not
    // parroting. "So the hardest part for you is ___." rather than "You said
    // 'hardest part is ___'".
    return `${opener} So what you are naming is ${echo}.`;
  }
  return opener;
}

